export const GODOT_STARTERS = {"action-3d":{"about":"A third-person action game: an ember temple at dusk with drawn-in-code textures, wind-blown grass, fire and a pond; a warrior with stamina, a dodge roll, light and heavy attacks, a flask and lock-on; a horned boss with telegraphed blows and a second phase; a bonfire checkpoint; touch controls on the phone (left thumb moves, right thumb turns the camera, buttons for the rest).","files":{"boss.gd":"extends CharacterBody3D\n## The Ember Warden: a horned giant with a burning maul. Every blow is\n## telegraphed (a wind-up, the maul glowing, a ring on the ground where it\n## will land), then the blow, then a recovery you can punish. Enough damage\n## in a short time staggers it. Below half health it roars into a second\n## phase: faster, with a burst of fire around it.\n\nsignal changed\nsignal woke\nsignal defeated\nsignal slammed(where: Vector3, strength: float)\n\nconst Fighter := preload(\"res://fighter.gd\")\nconst Look := preload(\"res://look.gd\")\nconst NAME := \"The Ember Warden\"\nconst GRAVITY := 24.0\nconst ATTACKS := {\n\t\"sweep\": {\"time\": 1.6, \"windup\": 0.72, \"window\": [0.72, 0.95], \"damage\": 26.0, \"reach\": 4.4, \"arc\": 120.0},\n\t\"slam\": {\"time\": 2.0, \"windup\": 1.0, \"window\": [1.0, 1.15], \"damage\": 40.0, \"radius\": 3.1, \"ahead\": 2.8},\n\t\"charge\": {\"time\": 1.9, \"windup\": 0.7, \"window\": [0.7, 1.35], \"damage\": 30.0, \"speed\": 13.0},\n\t\"burst\": {\"time\": 2.3, \"windup\": 1.2, \"window\": [1.2, 1.4], \"damage\": 34.0, \"radius\": 5.6},\n}\n\nvar max_hp := 900.0\nvar hp := 900.0\nvar radius := 1.1\nvar phase := 1\nvar state := \"dormant\"\nvar state_time := 0.0\nvar player: Node3D\nvar home := Vector3.ZERO\nvar facing := 0.0\nvar body: Node3D\nvar ring: MeshInstance3D\nvar ring_glow: StandardMaterial3D\nvar fire: GPUParticles3D\nvar _did_hit := false\nvar _slammed := false\nvar _poise := 0.0\nvar _poise_clock := 0.0\nvar _pause := 1.0\nvar _clock := 0.0\nvar _rng := RandomNumberGenerator.new()\n\n\nfunc _ready() -> void:\n\t_rng.seed = 17\n\tvar shape := CollisionShape3D.new()\n\tvar capsule := CapsuleShape3D.new()\n\tcapsule.radius = radius * 0.8\n\tcapsule.height = 3.6\n\tshape.shape = capsule\n\tshape.position.y = 1.8\n\tadd_child(shape)\n\tbody = Fighter.new()\n\tadd_child(body)\n\tbody.call(\"build\", {\"size\": 1.95, \"armour\": \"ember\", \"cloth\": \"leather\", \"skin\": \"ember\", \"cape\": \"leather\", \"weapon\": \"maul\", \"horns\": true, \"glow\": Color(1.0, 0.4, 0.08)})\n\tring = MeshInstance3D.new()\n\tvar disc := CylinderMesh.new()\n\tdisc.top_radius = 1.0\n\tdisc.bottom_radius = 1.0\n\tdisc.height = 0.03\n\tdisc.radial_segments = 48\n\tring.mesh = disc\n\tring_glow = Look.glow(Color(1.0, 0.3, 0.05, 0.0), 4.0, true)\n\tring.material_override = ring_glow\n\tring.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF\n\tring.top_level = true\n\tadd_child(ring)\n\tring.visible = false\n\tfire = Look.fire(1.6)\n\tfire.emitting = false\n\tadd_child(fire)\n\tfire.position.y = 1.4\n\thome = global_position\n\n\nfunc is_dead() -> bool:\n\treturn state == \"dead\"\n\n\nfunc reset() -> void:\n\thp = max_hp\n\tphase = 1\n\tglobal_position = home\n\tvelocity = Vector3.ZERO\n\tfacing = 0.0\n\t_poise = 0.0\n\t_pause = 1.0\n\t_start(\"dormant\")\n\tfire.emitting = false\n\tchanged.emit()\n\n\nfunc take_hit(damage: float, _from: Vector3) -> void:\n\tif state == \"dead\" or state == \"dormant\":\n\t\treturn\n\thp = maxf(0.0, hp - damage)\n\t_poise += damage\n\t_poise_clock = 0.0\n\tchanged.emit()\n\tif hp <= 0.0:\n\t\t_start(\"dead\")\n\t\tring.visible = false\n\t\tfire.emitting = false\n\t\tdefeated.emit()\n\telif phase == 1 and hp < max_hp * 0.5:\n\t\tphase = 2\n\t\t_poise = 0.0\n\t\tfire.emitting = true\n\t\t_start(\"roar\")\n\telif _poise > 110.0 and state not in [\"roar\", \"stagger\"]:\n\t\t_poise = 0.0\n\t\t_start(\"stagger\")\n\n\nfunc _start(next: String) -> void:\n\tstate = next\n\tstate_time = 0.0\n\t_did_hit = false\n\t_slammed = false\n\t# A new move starts clean: no ring or glow left from one cut short.\n\tif ring:\n\t\tring.visible = false\n\tvar glow: StandardMaterial3D = body.get(\"weapon_glow\") if body else null\n\tif glow:\n\t\tglow.emission_energy_multiplier = 0.0\n\n\nfunc _speed_up() -> float:\n\treturn 0.75 if phase == 2 else 1.0\n\n\nfunc _physics_process(delta: float) -> void:\n\t_clock += delta\n\tstate_time += delta\n\t_poise_clock += delta\n\tif _poise_clock > 4.0:\n\t\t_poise = 0.0\n\tif not is_on_floor():\n\t\tvelocity.y -= GRAVITY * delta\n\tvar to := Vector3.ZERO\n\tif player:\n\t\tto = player.global_position - global_position\n\t\tto.y = 0.0\n\tvar distance := to.length()\n\tvar player_down: bool = player != null and player.has_method(\"dead\") and player.call(\"dead\")\n\tvar shown := state\n\tvar progress := 0.0\n\tmatch state:\n\t\t\"dormant\":\n\t\t\tvelocity.x = 0.0\n\t\t\tvelocity.z = 0.0\n\t\t\tif player and distance < 17.0 and not player_down:\n\t\t\t\t_start(\"roar\")\n\t\t\t\twoke.emit()\n\t\t\"roar\":\n\t\t\t_stop(delta)\n\t\t\tprogress = state_time / 2.0\n\t\t\tif state_time > 2.0:\n\t\t\t\t_start(\"move\")\n\t\t\"stagger\":\n\t\t\t_stop(delta)\n\t\t\tprogress = state_time / 1.4\n\t\t\tif state_time > 1.4:\n\t\t\t\t_start(\"move\")\n\t\t\"dead\":\n\t\t\t_stop(delta)\n\t\t\tshown = \"dead\"\n\t\t\tprogress = state_time / 2.2\n\t\t\"move\":\n\t\t\tif player_down:\n\t\t\t\t_stop(delta)\n\t\t\t\tshown = \"idle\"\n\t\t\telse:\n\t\t\t\tfacing = lerp_angle(facing, atan2(-to.x, -to.z), minf(1.0, delta * 4.0))\n\t\t\t\tvar walk := 2.4 if phase == 1 else 3.4\n\t\t\t\tvar wanted := to.normalized() * (walk if distance > 3.2 else 0.0)\n\t\t\t\tvelocity.x = move_toward(velocity.x, wanted.x, 12.0 * delta)\n\t\t\t\tvelocity.z = move_toward(velocity.z, wanted.z, 12.0 * delta)\n\t\t\t\tshown = \"move\" if distance > 3.2 else \"idle\"\n\t\t\t\t_pause -= delta\n\t\t\t\tif _pause <= 0.0:\n\t\t\t\t\t_choose(distance)\n\t\t_:\n\t\t\tshown = state\n\t\t\tprogress = state_time / (float(ATTACKS[state][\"time\"]) * _speed_up())\n\t\t\t_attack(delta, to, distance)\n\tmove_and_slide()\n\tbody.rotation.y = facing\n\tvar speed := clampf(Vector2(velocity.x, velocity.z).length() / 3.4, 0.0, 1.0)\n\tbody.call(\"pose\", shown, _clock, clampf(progress, 0.0, 1.0), speed)\n\n\nfunc _stop(delta: float) -> void:\n\tvelocity.x = move_toward(velocity.x, 0.0, 20.0 * delta)\n\tvelocity.z = move_toward(velocity.z, 0.0, 20.0 * delta)\n\n\nfunc _choose(distance: float) -> void:\n\tvar options: Array[String] = []\n\tif distance > 7.5:\n\t\toptions = [\"charge\", \"charge\", \"slam\"]\n\telif distance < 4.6:\n\t\toptions = [\"sweep\", \"sweep\", \"slam\"]\n\telse:\n\t\toptions = [\"slam\", \"charge\", \"sweep\"]\n\tif phase == 2:\n\t\toptions.append(\"burst\")\n\t_start(options[_rng.randi_range(0, options.size() - 1)])\n\t_pause = _rng.randf_range(0.5, 1.1) * _speed_up()\n\n\nfunc _attack(delta: float, to: Vector3, distance: float) -> void:\n\tvar spec: Dictionary = ATTACKS[state]\n\tvar pace := _speed_up()\n\tvar windup := float(spec[\"windup\"]) * pace\n\tvar window: Array = spec[\"window\"]\n\tvar opens := float(window[0]) * pace\n\tvar closes := float(window[1]) * pace\n\tvar glow: StandardMaterial3D = body.get(\"weapon_glow\")\n\tglow.emission_energy_multiplier = lerpf(0.0, 9.0, clampf(state_time / windup, 0.0, 1.0)) if state_time < closes else maxf(0.0, glow.emission_energy_multiplier - delta * 12.0)\n\tif state_time < windup * 0.8:\n\t\tfacing = lerp_angle(facing, atan2(-to.x, -to.z), minf(1.0, delta * 5.0))\n\tvar ahead := Vector3(-sin(facing), 0, -cos(facing))\n\tmatch state:\n\t\t\"charge\":\n\t\t\tif state_time >= opens and state_time <= closes:\n\t\t\t\tvelocity.x = ahead.x * float(spec[\"speed\"])\n\t\t\t\tvelocity.z = ahead.z * float(spec[\"speed\"])\n\t\t\telse:\n\t\t\t\t_stop(delta)\n\t\t_:\n\t\t\t_stop(delta)\n\tif spec.has(\"radius\"):\n\t\tvar centre := global_position + (ahead * float(spec.get(\"ahead\", 0.0)))\n\t\tring.visible = state_time < closes\n\t\tring.global_position = Vector3(centre.x, global_position.y + 0.05, centre.z)\n\t\tvar grow := clampf(state_time / windup, 0.0, 1.0)\n\t\tring.scale = Vector3(float(spec[\"radius\"]) * grow, 1.0, float(spec[\"radius\"]) * grow)\n\t\tring_glow.albedo_color.a = 0.25 + 0.5 * grow\n\tif state_time >= opens and state_time <= closes and not _did_hit and player:\n\t\t_try_hit(spec, to, distance, ahead)\n\tif (state == \"slam\" or state == \"burst\") and state_time >= opens and not _slammed:\n\t\t_slammed = true\n\t\tslammed.emit(ring.global_position, 1.0 if state == \"slam\" else 1.4)\n\tif state_time >= float(spec[\"time\"]) * pace:\n\t\tring.visible = false\n\t\t_start(\"move\")\n\n\nfunc _try_hit(spec: Dictionary, to: Vector3, distance: float, ahead: Vector3) -> void:\n\tvar hit := false\n\tmatch state:\n\t\t\"sweep\":\n\t\t\thit = distance < float(spec[\"reach\"]) and (distance < 1.0 or rad_to_deg(ahead.angle_to(to.normalized())) < float(spec[\"arc\"]) * 0.5)\n\t\t\"slam\", \"burst\":\n\t\t\tvar flat := player.global_position - ring.global_position\n\t\t\tflat.y = 0.0\n\t\t\thit = flat.length() < float(spec[\"radius\"])\n\t\t\"charge\":\n\t\t\thit = distance < radius + 1.0\n\tif hit and player.call(\"take_hit\", float(spec[\"damage\"]), global_position):\n\t\t_did_hit = true\n","camera_rig.gd":"extends Node3D\n## The third-person camera: it follows the player smoothly on a spring arm\n## that pulls in when a wall is in the way, turns with the mouse or the right\n## stick, frames the target when locked on, and shakes on big hits.\n\nconst MOUSE := 0.0025\nconst STICK := 2.6\nconst FOLLOW := 10.0\n\nvar player: Node3D\nvar target: Node3D\nvar locked := false\nvar yaw := 0.0\nvar pitch := -0.32\nvar arm: SpringArm3D\nvar camera: Camera3D\nvar _shake := 0.0\nvar _rng := RandomNumberGenerator.new()\n\n\nfunc _ready() -> void:\n\tarm = SpringArm3D.new()\n\tarm.spring_length = 4.6\n\tarm.margin = 0.25\n\tadd_child(arm)\n\tcamera = Camera3D.new()\n\tcamera.fov = 60.0\n\tcamera.near = 0.08\n\tcamera.far = 600.0\n\tarm.add_child(camera)\n\tcamera.make_current()\n\n\nfunc follow(who: Node3D) -> void:\n\tplayer = who\n\tglobal_position = who.global_position + Vector3(0, 1.55, 0)\n\tif who is CollisionObject3D:\n\t\tarm.add_excluded_object((who as CollisionObject3D).get_rid())\n\n\nfunc shake(strength: float) -> void:\n\t_shake = maxf(_shake, strength)\n\n\nfunc _unhandled_input(event: InputEvent) -> void:\n\tif event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED and not locked:\n\t\tvar motion := event as InputEventMouseMotion\n\t\tyaw -= motion.relative.x * MOUSE\n\t\tpitch = clampf(pitch - motion.relative.y * MOUSE, -1.1, 0.35)\n\n\nfunc _process(delta: float) -> void:\n\tif not player:\n\t\treturn\n\tvar look := Input.get_vector(\"look_left\", \"look_right\", \"look_up\", \"look_down\")\n\tif not locked:\n\t\tyaw -= look.x * STICK * delta\n\t\tpitch = clampf(pitch - look.y * STICK * delta, -1.1, 0.35)\n\telif target:\n\t\tvar to := target.global_position - player.global_position\n\t\tvar wanted := atan2(-to.x, -to.z)\n\t\tyaw = lerp_angle(yaw, wanted, minf(1.0, delta * 6.0))\n\t\tpitch = lerpf(pitch, -0.28, minf(1.0, delta * 4.0))\n\tvar anchor := player.global_position + Vector3(0, 1.55, 0)\n\tglobal_position = global_position.lerp(anchor, minf(1.0, delta * FOLLOW))\n\trotation = Vector3(pitch, yaw, 0)\n\t_shake = maxf(0.0, _shake - delta * 2.5)\n\tcamera.h_offset = _rng.randf_range(-1.0, 1.0) * _shake * 0.15\n\tcamera.v_offset = _rng.randf_range(-1.0, 1.0) * _shake * 0.15\n","export_presets.cfg":"[preset.0]\n\nname=\"Windows Desktop\"\nplatform=\"Windows Desktop\"\nrunnable=true\nexport_filter=\"all_resources\"\ninclude_filter=\"\"\nexclude_filter=\"\"\nexport_path=\"build/game.exe\"\n\n[preset.0.options]\n\nbinary_format/embed_pck=true\n","fighter.gd":"extends Node3D\n## A fighter's body, built from shapes on jointed pivots (hips, spine, head,\n## shoulders, elbows, legs, knees) and dressed in armour, cloth and a cape,\n## with its poses: idle, move, roll, light, heavy, heal, hit, dead, and the\n## boss's sweep, slam, charge, burst and roar. The model faces -Z.\n## pose(state, time, progress, speed) is called every frame.\n\nconst Look := preload(\"res://look.gd\")\n\nvar hips: Node3D\nvar spine: Node3D\nvar head: Node3D\nvar arm_l: Node3D\nvar arm_r: Node3D\nvar elbow_l: Node3D\nvar elbow_r: Node3D\nvar leg_l: Node3D\nvar leg_r: Node3D\nvar knee_l: Node3D\nvar knee_r: Node3D\nvar cape: Node3D\nvar weapon: Node3D\nvar weapon_glow: StandardMaterial3D\nvar eye_glow: StandardMaterial3D\nvar height := 1.0\n\n\nfunc build(options: Dictionary) -> void:\n\theight = options.get(\"size\", 1.0)\n\tvar armour := Look.surface(options.get(\"armour\", \"steel\"), 4, 1.5)\n\tvar cloth := Look.surface(options.get(\"cloth\", \"cloth\"), 7, 2.5)\n\tvar skin := Look.surface(options.get(\"skin\", \"leather\"), 9, 2.5)\n\tvar trim := Look.surface(\"gold\", 5, 2.0)\n\thips = _joint(self, Vector3(0, 0.95, 0))\n\t_part(hips, _box(Vector3(0.38, 0.2, 0.24)), Vector3(0, 0.0, 0), skin)\n\t_part(hips, _box(Vector3(0.42, 0.34, 0.03)), Vector3(0, -0.2, -0.13), cloth)\n\t_part(hips, _box(Vector3(0.42, 0.34, 0.03)), Vector3(0, -0.2, 0.13), cloth)\n\tspine = _joint(hips, Vector3(0, 0.1, 0))\n\t_part(spine, _capsule(0.19, 0.6), Vector3(0, 0.32, 0), cloth)\n\t_part(spine, _box(Vector3(0.44, 0.36, 0.3)), Vector3(0, 0.44, 0), armour)\n\t_part(spine, _box(Vector3(0.46, 0.05, 0.31)), Vector3(0, 0.27, 0), trim)\n\tfor side: float in [-1.0, 1.0]:\n\t\tvar pauldron := _part(spine, _sphere(0.15), Vector3(side * 0.29, 0.6, 0), armour)\n\t\tpauldron.scale = Vector3(1.25, 0.75, 1.1)\n\thead = _joint(spine, Vector3(0, 0.72, 0))\n\t_part(head, _capsule(0.07, 0.12), Vector3(0, 0.03, 0), skin)\n\t_part(head, _sphere(0.14), Vector3(0, 0.17, 0), armour)\n\t_part(head, _box(Vector3(0.2, 0.025, 0.04)), Vector3(0, 0.16, -0.125), Look.glow(Color(0.02, 0.02, 0.02), 0.0))\n\tarm_l = _joint(spine, Vector3(-0.3, 0.6, 0))\n\tarm_r = _joint(spine, Vector3(0.3, 0.6, 0))\n\tfor arm: Node3D in [arm_l, arm_r]:\n\t\t_part(arm, _capsule(0.07, 0.34), Vector3(0, -0.17, 0), cloth)\n\telbow_l = _joint(arm_l, Vector3(0, -0.34, 0))\n\telbow_r = _joint(arm_r, Vector3(0, -0.34, 0))\n\tfor elbow: Node3D in [elbow_l, elbow_r]:\n\t\t_part(elbow, _capsule(0.07, 0.3), Vector3(0, -0.15, 0), armour)\n\t\t_part(elbow, _sphere(0.06), Vector3(0, -0.33, 0), skin)\n\tleg_l = _joint(hips, Vector3(-0.12, -0.04, 0))\n\tleg_r = _joint(hips, Vector3(0.12, -0.04, 0))\n\tfor leg: Node3D in [leg_l, leg_r]:\n\t\t_part(leg, _capsule(0.085, 0.44), Vector3(0, -0.22, 0), cloth)\n\tknee_l = _joint(leg_l, Vector3(0, -0.44, 0))\n\tknee_r = _joint(leg_r, Vector3(0, -0.44, 0))\n\tfor knee: Node3D in [knee_l, knee_r]:\n\t\t_part(knee, _capsule(0.08, 0.42), Vector3(0, -0.2, 0), armour)\n\t\t_part(knee, _box(Vector3(0.13, 0.08, 0.26)), Vector3(0, -0.44, -0.04), skin)\n\tcape = _joint(spine, Vector3(0, 0.66, 0.17))\n\t_part(cape, _box(Vector3(0.5, 1.0, 0.025)), Vector3(0, -0.5, 0), Look.surface(options.get(\"cape\", \"cloth\"), 12, 2.0))\n\tweapon = _joint(elbow_r, Vector3(0, -0.34, 0))\n\tweapon_glow = Look.glow(options.get(\"glow\", Color(1.0, 0.45, 0.12)), 0.0)\n\tif options.get(\"weapon\", \"sword\") == \"maul\":\n\t\t_part(weapon, _cylinder(0.035, 1.5), Vector3(0, 0, -0.55), Look.surface(\"bark\", 2, 3.0)).rotation.x = PI / 2\n\t\t_part(weapon, _box(Vector3(0.5, 0.36, 0.36)), Vector3(0, 0, -1.3), Look.surface(\"ember\", 6, 2.0))\n\t\t_part(weapon, _box(Vector3(0.52, 0.06, 0.38)), Vector3(0, 0, -1.3), weapon_glow)\n\telse:\n\t\t_part(weapon, _cylinder(0.025, 0.24), Vector3(0, 0, 0), Look.surface(\"leather\", 3, 4.0)).rotation.x = PI / 2\n\t\t_part(weapon, _box(Vector3(0.28, 0.04, 0.06)), Vector3(0, 0, -0.13), trim)\n\t\t_part(weapon, _box(Vector3(0.07, 0.016, 1.05)), Vector3(0, 0, -0.67), armour)\n\t\t_part(weapon, _box(Vector3(0.012, 0.018, 1.0)), Vector3(0, 0, -0.66), weapon_glow)\n\tif options.get(\"horns\", false):\n\t\teye_glow = Look.glow(Color(1.0, 0.35, 0.05), 6.0)\n\t\tfor side: float in [-1.0, 1.0]:\n\t\t\tvar horn := _part(head, _cone(0.07, 0.5), Vector3(side * 0.14, 0.32, 0.02), Look.surface(\"bark\", 8, 4.0))\n\t\t\thorn.rotation = Vector3(-0.35, 0, -side * 0.6)\n\t\t\t_part(head, _sphere(0.025), Vector3(side * 0.05, 0.17, -0.13), eye_glow)\n\tscale = Vector3.ONE * height\n\n\nfunc _joint(parent: Node3D, at: Vector3) -> Node3D:\n\tvar joint := Node3D.new()\n\tjoint.position = at\n\tparent.add_child(joint)\n\treturn joint\n\n\nfunc _part(parent: Node3D, mesh: Mesh, at: Vector3, material: Material) -> MeshInstance3D:\n\tvar part := MeshInstance3D.new()\n\tpart.mesh = mesh\n\tpart.material_override = material\n\tpart.position = at\n\tparent.add_child(part)\n\treturn part\n\n\nfunc _capsule(radius: float, length: float) -> CapsuleMesh:\n\tvar mesh := CapsuleMesh.new()\n\tmesh.radius = radius\n\tmesh.height = length + radius * 2.0\n\tmesh.radial_segments = 16\n\tmesh.rings = 6\n\treturn mesh\n\n\nfunc _box(size: Vector3) -> BoxMesh:\n\tvar mesh := BoxMesh.new()\n\tmesh.size = size\n\treturn mesh\n\n\nfunc _sphere(radius: float) -> SphereMesh:\n\tvar mesh := SphereMesh.new()\n\tmesh.radius = radius\n\tmesh.height = radius * 2.0\n\tmesh.radial_segments = 18\n\tmesh.rings = 10\n\treturn mesh\n\n\nfunc _cylinder(radius: float, length: float) -> CylinderMesh:\n\tvar mesh := CylinderMesh.new()\n\tmesh.top_radius = radius\n\tmesh.bottom_radius = radius\n\tmesh.height = length\n\tmesh.radial_segments = 10\n\treturn mesh\n\n\nfunc _cone(radius: float, length: float) -> CylinderMesh:\n\tvar mesh := CylinderMesh.new()\n\tmesh.top_radius = 0.0\n\tmesh.bottom_radius = radius\n\tmesh.height = length\n\tmesh.radial_segments = 10\n\treturn mesh\n\n\nstatic func _ease(x: float) -> float:\n\tvar v := clampf(x, 0.0, 1.0)\n\treturn v * v * (3.0 - 2.0 * v)\n\n\n## Pose the body: state, seconds alive, progress 0..1 of a one-off move,\n## and speed 0..1 (walk to run).\nfunc pose(state: String, t: float, k: float, speed: float) -> void:\n\tfor joint: Node3D in [hips, spine, head, arm_l, arm_r, elbow_l, elbow_r, leg_l, leg_r, knee_l, knee_r, cape]:\n\t\tjoint.rotation = Vector3.ZERO\n\thips.position = Vector3(0, 0.95, 0)\n\tvar breathe := sin(t * 2.0) * 0.025\n\tvar guard := func() -> void:\n\t\tarm_r.rotation = Vector3(-0.55, 0, 0.18)\n\t\telbow_r.rotation.x = -0.9\n\t\tarm_l.rotation = Vector3(-0.2, 0, -0.15)\n\t\telbow_l.rotation.x = -0.5\n\tmatch state:\n\t\t\"idle\", \"dormant\":\n\t\t\tguard.call()\n\t\t\tspine.rotation.x = breathe\n\t\t\thead.rotation.x = -breathe\n\t\t\tknee_l.rotation.x = 0.12\n\t\t\tknee_r.rotation.x = 0.12\n\t\t\thips.position.y = 0.94 + breathe * 0.3\n\t\t\"move\":\n\t\t\tvar pace := t * (7.0 + 5.0 * speed)\n\t\t\tvar stride := sin(pace) * (0.55 + 0.35 * speed)\n\t\t\tleg_l.rotation.x = stride\n\t\t\tleg_r.rotation.x = -stride\n\t\t\tknee_l.rotation.x = maxf(0.0, -sin(pace)) * (0.7 + 0.5 * speed)\n\t\t\tknee_r.rotation.x = maxf(0.0, sin(pace)) * (0.7 + 0.5 * speed)\n\t\t\tarm_l.rotation.x = -stride * 0.6\n\t\t\telbow_l.rotation.x = -0.4\n\t\t\tarm_r.rotation = Vector3(-0.5 + stride * 0.3, 0, 0.18)\n\t\t\telbow_r.rotation.x = -0.8\n\t\t\tspine.rotation.x = 0.08 + 0.18 * speed\n\t\t\thips.position.y = 0.95 + absf(cos(pace)) * 0.05\n\t\t\tcape.rotation.x = 0.2 + 0.35 * speed + sin(pace * 0.5) * 0.08\n\t\t\"roll\":\n\t\t\tvar arc := _ease(k)\n\t\t\thips.rotation.x = -arc * TAU\n\t\t\thips.position.y = 0.95 - sin(k * PI) * 0.5\n\t\t\tfor leg: Node3D in [leg_l, leg_r]:\n\t\t\t\tleg.rotation.x = -1.4\n\t\t\tknee_l.rotation.x = 2.0\n\t\t\tknee_r.rotation.x = 2.0\n\t\t\tarm_l.rotation.x = -1.2\n\t\t\tarm_r.rotation.x = -1.2\n\t\t\telbow_l.rotation.x = -1.4\n\t\t\telbow_r.rotation.x = -1.4\n\t\t\tspine.rotation.x = 0.7\n\t\t\"light\", \"sweep\":\n\t\t\tvar wind := _ease(k / 0.35)\n\t\t\tvar cut := _ease((k - 0.35) / 0.25)\n\t\t\tvar back := _ease((k - 0.7) / 0.3)\n\t\t\tvar swing := lerpf(lerpf(0.0, 1.0, wind), -1.0, cut)\n\t\t\tswing = lerpf(swing, 0.0, back)\n\t\t\tspine.rotation.y = swing * 0.7\n\t\t\tarm_r.rotation = Vector3(-1.5 + absf(swing) * 0.2, swing * 1.4, 0.4)\n\t\t\telbow_r.rotation.x = -0.3\n\t\t\tarm_l.rotation = Vector3(-0.3, 0, -0.3)\n\t\t\tleg_l.rotation.x = -0.35 * (1.0 - back)\n\t\t\tknee_r.rotation.x = 0.4\n\t\t\thips.position.y = 0.9\n\t\t\"heavy\", \"slam\":\n\t\t\tvar lift := _ease(k / 0.5)\n\t\t\tvar drop := _ease((k - 0.5) / 0.15)\n\t\t\tvar back := _ease((k - 0.75) / 0.25)\n\t\t\tvar raise := lerpf(lerpf(0.0, -2.9, lift), 0.4, drop)\n\t\t\traise = lerpf(raise, -0.5, back)\n\t\t\tarm_r.rotation = Vector3(raise, 0, 0.1)\n\t\t\tarm_l.rotation = Vector3(raise, 0, -0.1)\n\t\t\telbow_r.rotation.x = -0.3\n\t\t\telbow_l.rotation.x = -0.3\n\t\t\tspine.rotation.x = lerpf(-0.25 * lift, 0.5, drop) * (1.0 - back)\n\t\t\tknee_l.rotation.x = 0.5 * drop * (1.0 - back)\n\t\t\tknee_r.rotation.x = 0.5 * drop * (1.0 - back)\n\t\t\thips.position.y = 0.95 - 0.15 * drop * (1.0 - back)\n\t\t\"charge\":\n\t\t\tvar pace := t * 16.0\n\t\t\tvar stride := sin(pace) * 0.9\n\t\t\tleg_l.rotation.x = stride\n\t\t\tleg_r.rotation.x = -stride\n\t\t\tknee_l.rotation.x = maxf(0.0, -sin(pace)) * 1.2\n\t\t\tknee_r.rotation.x = maxf(0.0, sin(pace)) * 1.2\n\t\t\tspine.rotation.x = 0.5\n\t\t\tarm_r.rotation = Vector3(0.6, 0, 0.3)\n\t\t\tarm_l.rotation = Vector3(0.6, 0, -0.3)\n\t\t\"burst\", \"roar\":\n\t\t\tvar open := _ease(k / 0.4)\n\t\t\tspine.rotation.x = -0.45 * open\n\t\t\thead.rotation.x = -0.5 * open\n\t\t\tarm_l.rotation = Vector3(-0.5, 0, -1.4 * open)\n\t\t\tarm_r.rotation = Vector3(-0.5, 0, 1.4 * open)\n\t\t\tknee_l.rotation.x = 0.3\n\t\t\tknee_r.rotation.x = 0.3\n\t\t\"heal\":\n\t\t\tguard.call()\n\t\t\tarm_l.rotation = Vector3(-2.2 * _ease(k / 0.4), 0.4, 0)\n\t\t\telbow_l.rotation.x = -1.6\n\t\t\thead.rotation.x = 0.25\n\t\t\"hit\", \"stagger\":\n\t\t\tvar jolt := 1.0 - _ease(k)\n\t\t\tspine.rotation.x = -0.45 * jolt\n\t\t\thead.rotation.x = -0.4 * jolt\n\t\t\tarm_l.rotation.x = 0.6 * jolt\n\t\t\tarm_r.rotation.x = 0.4 * jolt\n\t\t\tknee_l.rotation.x = 0.4\n\t\t\tknee_r.rotation.x = 0.4\n\t\t\"dead\":\n\t\t\tvar fall := _ease(k)\n\t\t\thips.position.y = 0.95 - 0.78 * fall\n\t\t\thips.rotation.x = 1.45 * fall\n\t\t\tarm_l.rotation.z = -0.9 * fall\n\t\t\tarm_r.rotation.z = 0.9 * fall\n\t\t\tknee_l.rotation.x = 0.6 * fall\n\t\t\tknee_r.rotation.x = 0.2 * fall\n\tif state != \"move\":\n\t\tcape.rotation.x = maxf(cape.rotation.x, 0.08 + sin(t * 1.3) * 0.04)\n","grass.gdshader":"// Grass blades that sway in the wind, darker at the root and lit through\n// at the tip (each blade's colour comes from its instance colour).\nshader_type spatial;\nrender_mode cull_disabled, diffuse_burley;\n\nuniform vec3 root_color : source_color = vec3(0.10, 0.17, 0.06);\nuniform vec3 tip_color : source_color = vec3(0.55, 0.55, 0.22);\nuniform float wind = 0.32;\n\nvarying vec3 tint;\n\nvoid vertex() {\n\ttint = COLOR.rgb;\n\tvec3 world = (MODEL_MATRIX * vec4(0.0, 0.0, 0.0, 1.0)).xyz;\n\tfloat h = UV.y;\n\tfloat gust = sin(TIME * 1.6 + world.x * 0.31 + world.z * 0.23) + 0.45 * sin(TIME * 3.3 + world.z * 0.9);\n\tVERTEX.x += gust * wind * h * h;\n\tVERTEX.z += gust * wind * 0.4 * h * h;\n}\n\nvoid fragment() {\n\tvec3 color = mix(root_color, tip_color, UV.y) * tint;\n\tALBEDO = color;\n\tROUGHNESS = 0.85;\n\tSPECULAR = 0.25;\n\tBACKLIGHT = color * 0.6 * UV.y;\n}\n","hud.gd":"extends CanvasLayer\n## What's on the screen: health, stamina and flasks top left, the boss's name\n## and health at the bottom, big messages (FALLEN, VICTORY, Bonfire lit), a\n## prompt for things you can use, the controls (they fade), a vignette that\n## flashes red when you're hit, and the graphics line (F3).\n\nvar health: ProgressBar\nvar stamina: ProgressBar\nvar flasks: Label\nvar boss_box: VBoxContainer\nvar boss_bar: ProgressBar\nvar boss_name: Label\nvar message: Label\nvar prompt: Label\nvar help: Label\nvar info: Label\nvar vignette: ColorRect\nvar _fade: Tween\n\n\nfunc _ready() -> void:\n\tvignette = ColorRect.new()\n\tvignette.set_anchors_preset(Control.PRESET_FULL_RECT)\n\tvignette.mouse_filter = Control.MOUSE_FILTER_IGNORE\n\tvar shade := ShaderMaterial.new()\n\tshade.shader = preload(\"res://vignette.gdshader\")\n\tvignette.material = shade\n\tadd_child(vignette)\n\tvar top := VBoxContainer.new()\n\ttop.position = Vector2(36, 30)\n\ttop.add_theme_constant_override(\"separation\", 7)\n\tadd_child(top)\n\thealth = _bar(Color(\"#b3261e\"), 420, 16)\n\tstamina = _bar(Color(\"#5a8f3a\"), 320, 10)\n\ttop.add_child(health)\n\ttop.add_child(stamina)\n\tflasks = _label(20, Color(\"#f0c27a\"))\n\ttop.add_child(flasks)\n\tboss_box = VBoxContainer.new()\n\tboss_box.set_anchors_preset(Control.PRESET_CENTER_BOTTOM)\n\tboss_box.position = Vector2(-380, -96)\n\tboss_box.size = Vector2(760, 60)\n\tboss_box.visible = false\n\tadd_child(boss_box)\n\tboss_name = _label(22, Color(\"#e8dcc8\"))\n\tboss_box.add_child(boss_name)\n\tboss_bar = _bar(Color(\"#8f1d12\"), 760, 14)\n\tboss_box.add_child(boss_bar)\n\tmessage = _label(84, Color(\"#c9392b\"))\n\tmessage.set_anchors_preset(Control.PRESET_CENTER)\n\tmessage.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\tmessage.vertical_alignment = VERTICAL_ALIGNMENT_CENTER\n\tmessage.position = Vector2(-600, -70)\n\tmessage.size = Vector2(1200, 140)\n\tmessage.modulate.a = 0.0\n\tadd_child(message)\n\tprompt = _label(24, Color(\"#f2e8d5\"))\n\tprompt.set_anchors_preset(Control.PRESET_CENTER_BOTTOM)\n\tprompt.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\tprompt.position = Vector2(-300, -200)\n\tprompt.size = Vector2(600, 40)\n\tadd_child(prompt)\n\thelp = _label(17, Color(\"#e9e2d6\"))\n\thelp.set_anchors_preset(Control.PRESET_TOP_RIGHT)\n\thelp.position = Vector2(-470, 30)\n\thelp.size = Vector2(440, 200)\n\thelp.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT\n\tif DisplayServer.is_touchscreen_available():\n\t\thelp.text = \"Left thumb: move (push far to run)\\nRight thumb: turn the camera\\nHIT, HEAVY, ROLL, HEAL, LOCK, REST\"\n\telse:\n\t\thelp.text = \"WASD move - Shift run - Space roll\\nLeft click or J light - Right click or K heavy\\nArrows or mouse look - Q lock on - F flask\\nE rest at the bonfire - Click grabs the mouse, Esc frees it\\nF2 graphics - F3 info - a gamepad works too\"\n\tadd_child(help)\n\tvar fade := create_tween()\n\tfade.tween_interval(9.0)\n\tfade.tween_property(help, \"modulate:a\", 0.0, 2.0)\n\tinfo = _label(15, Color(\"#9fb3c8\"))\n\tinfo.set_anchors_preset(Control.PRESET_BOTTOM_LEFT)\n\tinfo.position = Vector2(36, -40)\n\tinfo.visible = false\n\tadd_child(info)\n\n\nfunc _bar(color: Color, width: float, height: float) -> ProgressBar:\n\tvar bar := ProgressBar.new()\n\tbar.custom_minimum_size = Vector2(width, height)\n\tbar.show_percentage = false\n\tvar back := StyleBoxFlat.new()\n\tback.bg_color = Color(0.03, 0.03, 0.03, 0.75)\n\tback.border_color = Color(0.75, 0.62, 0.42, 0.55)\n\tback.set_border_width_all(1)\n\tvar fill := StyleBoxFlat.new()\n\tfill.bg_color = color\n\tbar.add_theme_stylebox_override(\"background\", back)\n\tbar.add_theme_stylebox_override(\"fill\", fill)\n\treturn bar\n\n\nfunc _label(size: int, color: Color) -> Label:\n\tvar label := Label.new()\n\tlabel.add_theme_font_size_override(\"font_size\", size)\n\tlabel.add_theme_color_override(\"font_color\", color)\n\tlabel.add_theme_color_override(\"font_outline_color\", Color(0, 0, 0, 0.85))\n\tlabel.add_theme_constant_override(\"outline_size\", 8)\n\treturn label\n\n\nfunc show_player(hp: float, max_hp: float, stamina_now: float, max_stamina: float, flasks_left: int, flasks_max := 3) -> void:\n\thealth.max_value = max_hp\n\thealth.value = hp\n\tstamina.max_value = max_stamina\n\tstamina.value = stamina_now\n\tflasks.text = \"Flask  %d / %d\" % [flasks_left, flasks_max]\n\n\nfunc show_boss(title: String, hp: float, max_hp: float, visible_now: bool) -> void:\n\tboss_box.visible = visible_now\n\tboss_name.text = title\n\tboss_bar.max_value = max_hp\n\tboss_bar.value = hp\n\n\nfunc say(text: String, color: Color, seconds := 3.0) -> void:\n\tmessage.text = text\n\tmessage.add_theme_color_override(\"font_color\", color)\n\tif _fade and _fade.is_valid():\n\t\t_fade.kill()\n\t_fade = create_tween()\n\t_fade.tween_property(message, \"modulate:a\", 1.0, 0.6)\n\t_fade.tween_interval(seconds)\n\t_fade.tween_property(message, \"modulate:a\", 0.0, 1.0)\n\n\nfunc flash() -> void:\n\tvar shade := vignette.material as ShaderMaterial\n\tshade.set_shader_parameter(\"flash\", 1.0)\n\tvar fade := create_tween()\n\tfade.tween_method(func(value: float) -> void: shade.set_shader_parameter(\"flash\", value), 1.0, 0.0, 0.45)\n","look.gd":"extends RefCounted\n## The game's look, made in code so nothing needs a licence: surfaces drawn\n## from seamless noise (colour, bumps and roughness), glowing materials, and\n## fire, embers, smoke and sparks. Change a surface's colours here and every\n## model that uses it follows.\n\nconst SURFACES := {\n\t\"stone\": {\"colors\": [Color(\"#2e2c2b\"), Color(\"#5d5954\"), Color(\"#8f897f\")], \"frequency\": 0.018, \"bump\": 9.0, \"rough\": 0.92, \"metal\": 0.0},\n\t\"moss\": {\"colors\": [Color(\"#223014\"), Color(\"#3f5a22\"), Color(\"#6f8a3c\")], \"frequency\": 0.03, \"bump\": 5.0, \"rough\": 0.96, \"metal\": 0.0},\n\t\"bark\": {\"colors\": [Color(\"#1a120c\"), Color(\"#35261b\"), Color(\"#56402d\")], \"frequency\": 0.045, \"bump\": 14.0, \"rough\": 0.95, \"metal\": 0.0},\n\t\"steel\": {\"colors\": [Color(\"#22252a\"), Color(\"#4d535b\"), Color(\"#8e959e\")], \"frequency\": 0.07, \"bump\": 2.0, \"rough\": 0.34, \"metal\": 0.92},\n\t\"gold\": {\"colors\": [Color(\"#5a3d12\"), Color(\"#a07a2c\"), Color(\"#e2c06b\")], \"frequency\": 0.06, \"bump\": 1.5, \"rough\": 0.3, \"metal\": 1.0},\n\t\"cloth\": {\"colors\": [Color(\"#2a0907\"), Color(\"#5c1712\"), Color(\"#86281d\")], \"frequency\": 0.11, \"bump\": 3.0, \"rough\": 0.9, \"metal\": 0.0},\n\t\"leather\": {\"colors\": [Color(\"#1b120b\"), Color(\"#3b2717\"), Color(\"#5f4027\")], \"frequency\": 0.09, \"bump\": 4.0, \"rough\": 0.75, \"metal\": 0.0},\n\t\"wood\": {\"colors\": [Color(\"#2a1208\"), Color(\"#5a2414\"), Color(\"#7e3a1f\")], \"frequency\": 0.04, \"bump\": 6.0, \"rough\": 0.85, \"metal\": 0.0},\n\t\"roof\": {\"colors\": [Color(\"#101318\"), Color(\"#23282f\"), Color(\"#3a414b\")], \"frequency\": 0.05, \"bump\": 8.0, \"rough\": 0.7, \"metal\": 0.2},\n\t\"grass\": {\"colors\": [Color(\"#1d2a10\"), Color(\"#3a4d1d\"), Color(\"#66702e\")], \"frequency\": 0.03, \"bump\": 4.0, \"rough\": 0.95, \"metal\": 0.0},\n\t\"dirt\": {\"colors\": [Color(\"#2a1d14\"), Color(\"#4c3626\"), Color(\"#7a5c42\")], \"frequency\": 0.05, \"bump\": 7.0, \"rough\": 0.9, \"metal\": 0.0},\n\t\"rock\": {\"colors\": [Color(\"#25221f\"), Color(\"#4b4641\"), Color(\"#7b746b\")], \"frequency\": 0.025, \"bump\": 12.0, \"rough\": 0.9, \"metal\": 0.0},\n\t\"ember\": {\"colors\": [Color(\"#120a08\"), Color(\"#2b1610\"), Color(\"#3d1d12\")], \"frequency\": 0.06, \"bump\": 10.0, \"rough\": 0.8, \"metal\": 0.1},\n\t\"autumn\": {\"colors\": [Color(\"#4a1407\"), Color(\"#9a3b14\"), Color(\"#e07a2c\")], \"frequency\": 0.09, \"bump\": 6.0, \"rough\": 0.85, \"metal\": 0.0},\n\t\"pine\": {\"colors\": [Color(\"#0c1810\"), Color(\"#1b2f1d\"), Color(\"#33502d\")], \"frequency\": 0.1, \"bump\": 6.0, \"rough\": 0.9, \"metal\": 0.0},\n}\n\nstatic var _cache := {}\n\n\nstatic func noise(seed_value: int, frequency: float, octaves := 5) -> FastNoiseLite:\n\tvar made := FastNoiseLite.new()\n\tmade.seed = seed_value\n\tmade.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH\n\tmade.frequency = frequency\n\tmade.fractal_octaves = octaves\n\treturn made\n\n\nstatic func ramp(colors: Array) -> Gradient:\n\tvar gradient := Gradient.new()\n\tvar offsets := PackedFloat32Array()\n\tvar list := PackedColorArray()\n\tfor i in colors.size():\n\t\toffsets.append(float(i) / float(colors.size() - 1))\n\t\tlist.append(colors[i])\n\tgradient.offsets = offsets\n\tgradient.colors = list\n\treturn gradient\n\n\n## A seamless noise texture: colour (a ramp), bumps (a normal map) or roughness.\nstatic func texture(kind: String, seed_value: int, use: String, size := 512) -> NoiseTexture2D:\n\tvar recipe: Dictionary = SURFACES[kind]\n\tvar made := NoiseTexture2D.new()\n\t# A phone's browser draws them on one thread: smaller there.\n\tvar side := mini(size, 192) if OS.has_feature(\"web\") else size\n\tmade.width = side\n\tmade.height = side\n\tmade.seamless = true\n\tmade.noise = noise(seed_value, recipe[\"frequency\"])\n\tif use == \"normal\":\n\t\tmade.as_normal_map = true\n\t\tmade.bump_strength = recipe[\"bump\"]\n\telif use == \"rough\":\n\t\tvar base: float = recipe[\"rough\"]\n\t\tmade.color_ramp = ramp([Color(base - 0.15, base - 0.15, base - 0.15), Color(base, base, base), Color(min(base + 0.08, 1.0), min(base + 0.08, 1.0), min(base + 0.08, 1.0))])\n\telse:\n\t\tmade.color_ramp = ramp(recipe[\"colors\"])\n\treturn made\n\n\n## A full material for a surface, mapped by world position so it never\n## stretches (scale: how many times it repeats per metre).\nstatic func surface(kind: String, seed_value := 3, scale := 0.5) -> StandardMaterial3D:\n\tvar key := \"%s/%d/%s\" % [kind, seed_value, scale]\n\tif _cache.has(key):\n\t\treturn _cache[key]\n\tvar recipe: Dictionary = SURFACES[kind]\n\tvar material := StandardMaterial3D.new()\n\tmaterial.albedo_texture = texture(kind, seed_value, \"color\")\n\tmaterial.normal_enabled = true\n\tmaterial.normal_texture = texture(kind, seed_value + 11, \"normal\")\n\tmaterial.normal_scale = 1.0\n\tmaterial.roughness_texture = texture(kind, seed_value + 23, \"rough\", 256)\n\tmaterial.roughness = 1.0\n\tmaterial.metallic = recipe[\"metal\"]\n\tmaterial.metallic_specular = 0.5\n\tmaterial.uv1_triplanar = true\n\tmaterial.uv1_world_triplanar = true\n\tmaterial.uv1_scale = Vector3.ONE * scale\n\tmaterial.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS_ANISOTROPIC\n\t_cache[key] = material\n\treturn material\n\n\n## A material that glows (lanterns, eyes, embers, telegraph rings).\nstatic func glow(color: Color, energy := 3.0, see_through := false) -> StandardMaterial3D:\n\tvar material := StandardMaterial3D.new()\n\tmaterial.albedo_color = color\n\tmaterial.emission_enabled = true\n\tmaterial.emission = color\n\tmaterial.emission_energy_multiplier = energy\n\tmaterial.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED\n\tif see_through:\n\t\tmaterial.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA\n\t\tmaterial.blend_mode = BaseMaterial3D.BLEND_MODE_ADD\n\t\tmaterial.cull_mode = BaseMaterial3D.CULL_DISABLED\n\treturn material\n\n\nstatic func soft_dot() -> GradientTexture2D:\n\tif _cache.has(\"dot\"):\n\t\treturn _cache[\"dot\"]\n\tvar dot := GradientTexture2D.new()\n\tdot.fill = GradientTexture2D.FILL_RADIAL\n\tdot.fill_from = Vector2(0.5, 0.5)\n\tdot.fill_to = Vector2(0.5, 0.0)\n\tdot.width = 64\n\tdot.height = 64\n\tvar gradient := Gradient.new()\n\tgradient.set_color(0, Color(1, 1, 1, 1))\n\tgradient.set_color(1, Color(1, 1, 1, 0))\n\tdot.gradient = gradient\n\t_cache[\"dot\"] = dot\n\treturn dot\n\n\nstatic func _sprite(size: float, add := true) -> QuadMesh:\n\tvar quad := QuadMesh.new()\n\tquad.size = Vector2(size, size)\n\tvar material := StandardMaterial3D.new()\n\tmaterial.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED\n\tmaterial.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA\n\tif add:\n\t\tmaterial.blend_mode = BaseMaterial3D.BLEND_MODE_ADD\n\tmaterial.billboard_mode = BaseMaterial3D.BILLBOARD_PARTICLES\n\tmaterial.vertex_color_use_as_albedo = true\n\tmaterial.albedo_texture = soft_dot()\n\tquad.material = material\n\treturn quad\n\n\nstatic func _shrink() -> CurveTexture:\n\tvar curve := Curve.new()\n\tcurve.add_point(Vector2(0, 0.6))\n\tcurve.add_point(Vector2(0.25, 1.0))\n\tcurve.add_point(Vector2(1, 0.1))\n\tvar made := CurveTexture.new()\n\tmade.curve = curve\n\treturn made\n\n\nstatic func _colors(stops: Array) -> GradientTexture1D:\n\tvar made := GradientTexture1D.new()\n\tvar gradient := Gradient.new()\n\tvar offsets := PackedFloat32Array()\n\tvar list := PackedColorArray()\n\tfor stop: Array in stops:\n\t\toffsets.append(stop[0])\n\t\tlist.append(stop[1])\n\tgradient.offsets = offsets\n\tgradient.colors = list\n\tmade.gradient = gradient\n\treturn made\n\n\nstatic func _particles(amount: int, life: float, quad: float, add := true) -> GPUParticles3D:\n\tvar made := GPUParticles3D.new()\n\tmade.amount = amount\n\tmade.lifetime = life\n\tmade.draw_pass_1 = _sprite(quad, add)\n\tmade.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF\n\tmade.visibility_aabb = AABB(Vector3(-20, -2, -20), Vector3(40, 30, 40))\n\treturn made\n\n\n## Flames: a hot core that rises, reddens and fades (size in metres).\nstatic func fire(size := 1.0) -> GPUParticles3D:\n\tvar made := _particles(int(36 * size) + 12, 0.8, 0.55 * size)\n\tvar process := ParticleProcessMaterial.new()\n\tprocess.emission_shape = ParticleProcessMaterial.EMISSION_SHAPE_SPHERE\n\tprocess.emission_sphere_radius = 0.28 * size\n\tprocess.direction = Vector3.UP\n\tprocess.spread = 10.0\n\tprocess.initial_velocity_min = 0.6 * size\n\tprocess.initial_velocity_max = 1.6 * size\n\tprocess.gravity = Vector3(0, 2.4 * size, 0)\n\tprocess.damping_min = 0.5\n\tprocess.damping_max = 1.0\n\tprocess.scale_min = 0.7\n\tprocess.scale_max = 1.3\n\tprocess.scale_curve = _shrink()\n\tprocess.color_ramp = _colors([[0.0, Color(1.0, 0.78, 0.45, 0.55)], [0.2, Color(1.0, 0.48, 0.12, 0.5)], [0.55, Color(0.8, 0.18, 0.04, 0.32)], [1.0, Color(0.2, 0.05, 0.02, 0.0)]])\n\tmade.process_material = process\n\treturn made\n\n\n## Embers drifting up through a box of air (area: its size).\nstatic func embers(area: Vector3, amount := 260) -> GPUParticles3D:\n\tvar made := _particles(amount, 6.0, 0.09)\n\tvar process := ParticleProcessMaterial.new()\n\tprocess.emission_shape = ParticleProcessMaterial.EMISSION_SHAPE_BOX\n\tprocess.emission_box_extents = area * 0.5\n\tprocess.direction = Vector3.UP\n\tprocess.spread = 35.0\n\tprocess.initial_velocity_min = 0.3\n\tprocess.initial_velocity_max = 1.1\n\tprocess.gravity = Vector3(0.35, 0.5, 0.1)\n\tprocess.turbulence_enabled = true\n\tprocess.turbulence_noise_strength = 1.2\n\tprocess.turbulence_noise_scale = 4.0\n\tprocess.color_ramp = _colors([[0.0, Color(1.0, 0.75, 0.3, 0.0)], [0.15, Color(1.0, 0.6, 0.2, 1.0)], [0.8, Color(1.0, 0.3, 0.08, 0.8)], [1.0, Color(0.6, 0.1, 0.0, 0.0)]])\n\tmade.process_material = process\n\tmade.visibility_aabb = AABB(-area * 0.5 - Vector3(2, 2, 2), area + Vector3(4, 14, 4))\n\treturn made\n\n\n## Slow grey smoke over a fire.\nstatic func smoke(size := 1.0) -> GPUParticles3D:\n\tvar made := _particles(int(18 * size) + 6, 4.0, 1.6 * size, false)\n\tvar process := ParticleProcessMaterial.new()\n\tprocess.emission_shape = ParticleProcessMaterial.EMISSION_SHAPE_SPHERE\n\tprocess.emission_sphere_radius = 0.3 * size\n\tprocess.direction = Vector3.UP\n\tprocess.spread = 15.0\n\tprocess.initial_velocity_min = 0.4\n\tprocess.initial_velocity_max = 0.9\n\tprocess.gravity = Vector3(0.2, 0.3, 0.0)\n\tprocess.scale_min = 0.8\n\tprocess.scale_max = 1.8\n\tprocess.color_ramp = _colors([[0.0, Color(0.2, 0.18, 0.17, 0.0)], [0.2, Color(0.25, 0.22, 0.2, 0.35)], [1.0, Color(0.3, 0.28, 0.27, 0.0)]])\n\tmade.process_material = process\n\treturn made\n\n\n## A burst of sparks for a hit (call restart() to fire it).\nstatic func sparks(color := Color(1.0, 0.7, 0.3)) -> GPUParticles3D:\n\tvar made := _particles(40, 0.5, 0.12)\n\tmade.one_shot = true\n\tmade.explosiveness = 0.95\n\tmade.emitting = false\n\tvar process := ParticleProcessMaterial.new()\n\tprocess.direction = Vector3.UP\n\tprocess.spread = 80.0\n\tprocess.initial_velocity_min = 3.0\n\tprocess.initial_velocity_max = 7.0\n\tprocess.gravity = Vector3(0, -12, 0)\n\tprocess.color_ramp = _colors([[0.0, Color(1, 1, 0.9, 1)], [0.3, color], [1.0, Color(color.r, color.g * 0.4, 0.0, 0.0)]])\n\tmade.process_material = process\n\treturn made\n","main.gd":"extends Node3D\n## The Ember Temple at dusk: a valley with a stone path between torches and\n## burning trees, a ring of ruined pillars round the arena, a five-tier\n## pagoda, a still pond, wind in the grass, embers in the air and mist on\n## the ground. The bonfire is your checkpoint; the Ember Warden waits in the\n## arena. Change the place in WORLD, the surfaces in look.gd, the fight in\n## player.gd and boss.gd. F2 cycles the graphics: Low, Medium, High, Ultra.\n\nconst Look := preload(\"res://look.gd\")\nconst PlayerScript := preload(\"res://player.gd\")\nconst BossScript := preload(\"res://boss.gd\")\nconst RigScript := preload(\"res://camera_rig.gd\")\nconst HudScript := preload(\"res://hud.gd\")\nconst TouchScript := preload(\"res://touch.gd\")\n\nconst WORLD := {\n\t\"size\": 170.0,\n\t\"cells\": 150,\n\t\"arena\": Vector3(0, 0, -14),\n\t\"arena_radius\": 17.0,\n\t\"spawn\": Vector3(0, 0, 31),\n\t\"bonfire\": Vector3(2.8, 0, 26),\n\t\"pagoda\": Vector3(0, 0, -52),\n\t\"pond\": Vector3(25, 0, 9),\n\t\"pond_radius\": 7.5,\n\t\"sun\": Color(\"#ffa765\"),\n\t\"sky_top\": Color(\"#121833\"),\n\t\"horizon\": Color(\"#d9623d\"),\n\t\"fog\": Color(\"#8a5a4a\"),\n}\nconst GRAPHICS := [\"Low\", \"Medium\", \"High\", \"Ultra\"]\n\n## High on a PC; Medium in a phone's browser (one thread, the simpler renderer).\nvar graphics := 1 if OS.has_feature(\"web\") else 2\nvar height_noise := Look.noise(5, 0.012, 4)\nvar environment: Environment\nvar sun: DirectionalLight3D\nvar grass: MultiMeshInstance3D\nvar player: CharacterBody3D\nvar boss: CharacterBody3D\nvar rig: Node3D\nvar hud: CanvasLayer\nvar sparks: GPUParticles3D\nvar flames: Array[OmniLight3D] = []\nvar won := false\nvar _boss_awake := false\nvar _last_hp := 100.0\nvar _clock := 0.0\nvar _rng := RandomNumberGenerator.new()\n\n\nfunc _ready() -> void:\n\t_rng.seed = 2024\n\t_add_inputs()\n\t_add_sky_and_light()\n\t_add_terrain()\n\t_add_pond()\n\t_add_arena()\n\t_add_pagoda()\n\t_add_trees()\n\t_add_grass()\n\t_add_rocks()\n\t_add_torches()\n\t_add_bonfire()\n\t_add_air()\n\tplayer = PlayerScript.new()\n\tadd_child(player)\n\tvar spawn: Vector3 = WORLD[\"spawn\"]\n\tplayer.global_position = Vector3(spawn.x, height_at(spawn.x, spawn.z) + 0.2, spawn.z)\n\tboss = BossScript.new()\n\tadd_child(boss)\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tboss.global_position = Vector3(arena.x, 0.2, arena.z - 3.0)\n\tboss.set(\"home\", boss.global_position)\n\tboss.set(\"player\", player)\n\tplayer.set(\"target\", boss)\n\trig = RigScript.new()\n\tadd_child(rig)\n\trig.call(\"follow\", player)\n\thud = HudScript.new()\n\tadd_child(hud)\n\tvar touch := TouchScript.new()\n\ttouch.set(\"rig\", rig)\n\tadd_child(touch)\n\tsparks = Look.sparks()\n\tadd_child(sparks)\n\tplayer.connect(\"changed\", _on_player_changed)\n\tplayer.connect(\"died\", _on_player_died)\n\tplayer.connect(\"struck\", _on_struck)\n\tboss.connect(\"changed\", _on_boss_changed)\n\tboss.connect(\"woke\", _on_boss_woke)\n\tboss.connect(\"defeated\", _on_boss_defeated)\n\tboss.connect(\"slammed\", _on_slammed)\n\tapply_graphics()\n\t_on_player_changed()\n\t_on_boss_changed()\n\n\n# ------------------------------------------------------------------ ground\n\nfunc path_x(z: float) -> float:\n\treturn sin(z * 0.075) * 3.2\n\n\n## How much of the stone path is here (0..1).\nfunc path_mask(x: float, z: float) -> float:\n\tif z > 46.0 or z < -62.0:\n\t\treturn 0.0\n\treturn 1.0 - smoothstep(2.2, 4.6, absf(x - path_x(z)))\n\n\nfunc height_at(x: float, z: float) -> float:\n\tvar h := height_noise.get_noise_2d(x, z) * 5.0\n\th += maxf(0.0, Vector2(x, z).length() - 48.0) * 0.34\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tvar flat := 1.0 - smoothstep(radius + 2.0, radius + 10.0, Vector2(x - arena.x, z - arena.z).length())\n\th = lerpf(h, 0.0, flat)\n\th = lerpf(h, h * 0.25, path_mask(x, z))\n\tvar pagoda: Vector3 = WORLD[\"pagoda\"]\n\th = lerpf(h, 0.0, 1.0 - smoothstep(10.0, 16.0, Vector2(x - pagoda.x, z - pagoda.z).length()))\n\tvar pond: Vector3 = WORLD[\"pond\"]\n\tvar pond_radius: float = WORLD[\"pond_radius\"]\n\th -= (1.0 - smoothstep(pond_radius - 2.5, pond_radius + 1.5, Vector2(x - pond.x, z - pond.z).length())) * 1.7\n\treturn h\n\n\nfunc _add_terrain() -> void:\n\tvar size: float = WORLD[\"size\"]\n\tvar cells: int = WORLD[\"cells\"]\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tvar step := size / cells\n\tvar tool := SurfaceTool.new()\n\ttool.begin(Mesh.PRIMITIVE_TRIANGLES)\n\tfor iz in cells + 1:\n\t\tfor ix in cells + 1:\n\t\t\tvar x := -size / 2.0 + ix * step\n\t\t\tvar z := -size / 2.0 + iz * step\n\t\t\tvar worn := 1.0 - smoothstep(radius - 1.0, radius + 4.0, Vector2(x - arena.x, z - arena.z).length())\n\t\t\ttool.set_color(Color(maxf(path_mask(x, z), worn), 0, 0))\n\t\t\ttool.set_uv(Vector2(ix, iz) / cells)\n\t\t\ttool.add_vertex(Vector3(x, height_at(x, z), z))\n\tfor iz in cells:\n\t\tfor ix in cells:\n\t\t\tvar a := iz * (cells + 1) + ix\n\t\t\tvar c := a + cells + 1\n\t\t\tfor index: int in [a, a + 1, c, a + 1, c + 1, c]:\n\t\t\t\ttool.add_index(index)\n\ttool.generate_normals()\n\ttool.generate_tangents()\n\tvar mesh := tool.commit()\n\tvar ground := ShaderMaterial.new()\n\tground.shader = preload(\"res://terrain.gdshader\")\n\tground.set_shader_parameter(\"grass_tex\", Look.texture(\"grass\", 31, \"color\"))\n\tground.set_shader_parameter(\"dirt_tex\", Look.texture(\"dirt\", 32, \"color\"))\n\tground.set_shader_parameter(\"rock_tex\", Look.texture(\"rock\", 33, \"color\"))\n\tground.set_shader_parameter(\"bumps\", Look.texture(\"rock\", 34, \"normal\"))\n\tvar land := MeshInstance3D.new()\n\tland.mesh = mesh\n\tland.material_override = ground\n\tadd_child(land)\n\tvar body := StaticBody3D.new()\n\tvar shape := CollisionShape3D.new()\n\tshape.shape = mesh.create_trimesh_shape()\n\tbody.add_child(shape)\n\tadd_child(body)\n\n\nfunc _add_pond() -> void:\n\tvar pond: Vector3 = WORLD[\"pond\"]\n\tvar water := MeshInstance3D.new()\n\tvar plane := PlaneMesh.new()\n\tvar radius: float = WORLD[\"pond_radius\"]\n\tplane.size = Vector2(radius * 2.4, radius * 2.4)\n\tplane.subdivide_width = 24\n\tplane.subdivide_depth = 24\n\tvar material := ShaderMaterial.new()\n\tmaterial.shader = preload(\"res://water.gdshader\")\n\tplane.material = material\n\twater.mesh = plane\n\twater.position = Vector3(pond.x, -0.75, pond.z)\n\twater.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF\n\tadd_child(water)\n\n\n# ------------------------------------------------------------------ places\n\nfunc _solid(mesh: Mesh, material: Material, at: Vector3, shape: Shape3D = null, turn := Vector3.ZERO) -> MeshInstance3D:\n\tvar item := MeshInstance3D.new()\n\titem.mesh = mesh\n\titem.material_override = material\n\tif shape:\n\t\tvar body := StaticBody3D.new()\n\t\tbody.position = at\n\t\tbody.rotation = turn\n\t\tvar collider := CollisionShape3D.new()\n\t\tcollider.shape = shape\n\t\tbody.add_child(collider)\n\t\tbody.add_child(item)\n\t\tadd_child(body)\n\telse:\n\t\titem.position = at\n\t\titem.rotation = turn\n\t\tadd_child(item)\n\treturn item\n\n\nfunc _box(size: Vector3) -> BoxMesh:\n\tvar mesh := BoxMesh.new()\n\tmesh.size = size\n\treturn mesh\n\n\nfunc _box_shape(size: Vector3) -> BoxShape3D:\n\tvar shape := BoxShape3D.new()\n\tshape.size = size\n\treturn shape\n\n\nfunc _cylinder(top: float, bottom: float, height: float, sides := 20) -> CylinderMesh:\n\tvar mesh := CylinderMesh.new()\n\tmesh.top_radius = top\n\tmesh.bottom_radius = bottom\n\tmesh.height = height\n\tmesh.radial_segments = sides\n\treturn mesh\n\n\nfunc _cylinder_shape(radius: float, height: float) -> CylinderShape3D:\n\tvar shape := CylinderShape3D.new()\n\tshape.radius = radius\n\tshape.height = height\n\treturn shape\n\n\nfunc _add_arena() -> void:\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tvar stone := Look.surface(\"stone\", 3, 0.35)\n\tvar moss := Look.surface(\"moss\", 4, 0.4)\n\t_solid(_cylinder(radius - 1.5, radius - 1.2, 0.5, 64), stone, arena + Vector3(0, -0.2, 0), _cylinder_shape(radius - 1.2, 0.5))\n\tfor i in 14:\n\t\tvar angle := TAU * i / 14.0 + 0.11\n\t\tif absf(wrapf(angle - PI / 2.0, -PI, PI)) < 0.25:\n\t\t\tcontinue\n\t\tvar at := arena + Vector3(cos(angle) * (radius + 1.8), 0, sin(angle) * (radius + 1.8))\n\t\tvar broken := i % 3 == 1\n\t\tvar tall := 2.6 if broken else _rng.randf_range(6.0, 7.5)\n\t\t_solid(_box(Vector3(2.0, 0.7, 2.0)), moss, at + Vector3(0, 0.35, 0), _box_shape(Vector3(2.0, 0.7, 2.0)))\n\t\t_solid(_cylinder(0.6, 0.72, tall, 16), stone, at + Vector3(0, 0.7 + tall / 2.0, 0), _cylinder_shape(0.72, tall))\n\t\tif broken:\n\t\t\t_solid(_cylinder(0.6, 0.6, 3.6, 16), stone, at + Vector3(_rng.randf_range(-2.5, 2.5), 0.6, _rng.randf_range(1.0, 2.5)), _cylinder_shape(0.6, 3.6), Vector3(0, _rng.randf() * TAU, PI / 2.0))\n\t\telse:\n\t\t\t_solid(_box(Vector3(1.8, 0.6, 1.8)), stone, at + Vector3(0, 0.7 + tall + 0.3, 0))\n\t# The gate on the path into the arena, with a torn banner.\n\tvar gate := arena + Vector3(0, 0, radius + 4.0)\n\tfor side: float in [-1.0, 1.0]:\n\t\t_solid(_box(Vector3(1.6, 8.0, 1.6)), stone, gate + Vector3(side * 4.2, 4.0, 0), _box_shape(Vector3(1.6, 8.0, 1.6)))\n\t_solid(_box(Vector3(11.0, 1.2, 2.0)), stone, gate + Vector3(0, 8.4, 0))\n\t_solid(_box(Vector3(9.4, 0.25, 2.2)), Look.surface(\"roof\", 5, 0.6), gate + Vector3(0, 9.1, 0))\n\t_solid(_box(Vector3(2.4, 4.2, 0.05)), Look.surface(\"cloth\", 6, 0.8), gate + Vector3(0, 5.6, 0.2))\n\n\nfunc _add_pagoda() -> void:\n\tvar at: Vector3 = WORLD[\"pagoda\"]\n\tvar stone := Look.surface(\"stone\", 7, 0.35)\n\tvar wood := Look.surface(\"wood\", 8, 0.5)\n\tvar roof := Look.surface(\"roof\", 9, 0.5)\n\tvar gold := Look.surface(\"gold\", 10, 1.0)\n\t_solid(_box(Vector3(18, 1.6, 18)), stone, at + Vector3(0, 0.8, 0), _box_shape(Vector3(18, 1.6, 18)))\n\tfor step in 5:\n\t\t_solid(_box(Vector3(8, 0.32, 1.2)), stone, at + Vector3(0, 0.16 + step * 0.32, 9.0 + (4 - step) * 1.1), _box_shape(Vector3(8, 0.32, 1.2)))\n\tvar y := 1.6\n\tfor tier in 5:\n\t\tvar width := 10.0 - tier * 1.45\n\t\tvar wall := 2.6 - tier * 0.22\n\t\t_solid(_box(Vector3(width, wall, width)), wood, at + Vector3(0, y + wall / 2.0, 0), _box_shape(Vector3(width, wall, width)) if tier == 0 else null)\n\t\t_solid(_box(Vector3(width + 0.3, 0.18, width + 0.3)), gold, at + Vector3(0, y + wall, 0))\n\t\tvar eaves := _solid(_cylinder(width * 0.38, width * 0.98, 1.4, 4), roof, at + Vector3(0, y + wall + 0.7, 0))\n\t\teaves.rotation.y = PI / 4.0\n\t\tif tier < 2:\n\t\t\tfor corner: Vector2 in [Vector2(1, 1), Vector2(-1, 1), Vector2(1, -1), Vector2(-1, -1)]:\n\t\t\t\tvar lamp := at + Vector3(corner.x * width * 0.62, y + wall + 0.1, corner.y * width * 0.62)\n\t\t\t\t_solid(_box(Vector3(0.35, 0.5, 0.35)), Look.glow(Color(\"#ffb04a\"), 4.0), lamp)\n\t\t\tvar light := OmniLight3D.new()\n\t\t\tlight.light_color = Color(\"#ff9a45\")\n\t\t\tlight.light_energy = 2.4\n\t\t\tlight.omni_range = 14.0\n\t\t\tlight.position = at + Vector3(0, y + wall, width * 0.62)\n\t\t\tadd_child(light)\n\t\t\tflames.append(light)\n\t\ty += wall + 1.1\n\t_solid(_cylinder(0.08, 0.2, 3.2, 10), gold, at + Vector3(0, y + 1.6, 0))\n\tvar orb := SphereMesh.new()\n\torb.radius = 0.3\n\torb.height = 0.6\n\t_solid(orb, Look.glow(Color(\"#ffcf7a\"), 5.0), at + Vector3(0, y + 3.3, 0))\n\n\nfunc _add_trees() -> void:\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tvar pond: Vector3 = WORLD[\"pond\"]\n\tvar pagoda: Vector3 = WORLD[\"pagoda\"]\n\tvar placed := 0\n\tvar tries := 0\n\twhile placed < 95 and tries < 1500:\n\t\ttries += 1\n\t\tvar angle := _rng.randf() * TAU\n\t\tvar distance := _rng.randf_range(24.0, 80.0)\n\t\tvar x := cos(angle) * distance\n\t\tvar z := sin(angle) * distance\n\t\tif path_mask(x, z) > 0.02 or absf(x - path_x(z)) < 6.0 and z > -60.0 and z < 46.0:\n\t\t\tcontinue\n\t\tif Vector2(x - arena.x, z - arena.z).length() < radius + 6.0 or Vector2(x - pond.x, z - pond.z).length() < 11.0 or Vector2(x - pagoda.x, z - pagoda.z).length() < 16.0:\n\t\t\tcontinue\n\t\t_tree(Vector3(x, height_at(x, z), z), _rng.randf() < 0.55, false)\n\t\tplaced += 1\n\tfor i in 8:\n\t\tvar angle := TAU * (i + 0.5) / 8.0\n\t\tif absf(wrapf(angle - PI / 2.0, -PI, PI)) < 0.5:\n\t\t\tcontinue\n\t\tvar x := arena.x + cos(angle) * (radius + 8.0)\n\t\tvar z := arena.z + sin(angle) * (radius + 8.0)\n\t\t_tree(Vector3(x, height_at(x, z), z), false, true)\n\n\nfunc _tree(at: Vector3, pine: bool, burning: bool) -> void:\n\tvar tall := _rng.randf_range(5.5, 9.0)\n\tvar trunk := _cylinder(0.16, 0.38, tall, 10)\n\t_solid(trunk, Look.surface(\"bark\", 11, 0.6), at + Vector3(0, tall / 2.0, 0), _cylinder_shape(0.38, tall))\n\tif pine:\n\t\tvar needles := Look.surface(\"pine\", 12, 0.6)\n\t\tfor layer in 4:\n\t\t\tvar width := 2.8 - layer * 0.55\n\t\t\t_solid(_cylinder(0.0, width, 2.8, 12), needles, at + Vector3(0, tall * 0.42 + layer * 1.35, 0))\n\t\treturn\n\tvar leaves := Look.surface(\"autumn\", 13, 0.6)\n\tif burning:\n\t\tleaves = leaves.duplicate() as StandardMaterial3D\n\t\tleaves.emission_enabled = true\n\t\tleaves.emission = Color(\"#ff5a14\")\n\t\tleaves.emission_energy_multiplier = 0.6\n\tfor i in 6:\n\t\tvar ball := SphereMesh.new()\n\t\tvar size := _rng.randf_range(1.4, 2.3)\n\t\tball.radius = size\n\t\tball.height = size * 1.7\n\t\tball.radial_segments = 12\n\t\tball.rings = 8\n\t\t_solid(ball, leaves, at + Vector3(_rng.randf_range(-1.4, 1.4), tall * 0.85 + _rng.randf_range(-0.6, 1.4), _rng.randf_range(-1.4, 1.4)))\n\tif burning:\n\t\tvar fire := Look.fire(2.4)\n\t\tfire.position = at + Vector3(0, tall * 0.9, 0)\n\t\tadd_child(fire)\n\t\tvar smoke := Look.smoke(2.0)\n\t\tsmoke.position = at + Vector3(0, tall + 1.5, 0)\n\t\tadd_child(smoke)\n\t\tvar light := OmniLight3D.new()\n\t\tlight.light_color = Color(\"#ff6a1f\")\n\t\tlight.light_energy = 2.2\n\t\tlight.omni_range = 11.0\n\t\tlight.position = at + Vector3(0, tall * 0.8, 0)\n\t\tadd_child(light)\n\t\tflames.append(light)\n\n\nfunc _blade() -> ArrayMesh:\n\tvar tool := SurfaceTool.new()\n\ttool.begin(Mesh.PRIMITIVE_TRIANGLES)\n\ttool.set_normal(Vector3(0, 1, 0.35).normalized())\n\tvar rows := [[0.0, 0.035], [0.4, 0.027], [0.75, 0.014]]\n\tfor row: Array in rows:\n\t\tfor side: float in [-1.0, 1.0]:\n\t\t\ttool.set_uv(Vector2(0.5 + side * 0.5, row[0]))\n\t\t\ttool.add_vertex(Vector3(side * float(row[1]), float(row[0]) * 0.55, 0))\n\ttool.set_uv(Vector2(0.5, 1.0))\n\ttool.add_vertex(Vector3(0, 0.55, 0.03))\n\tfor index: int in [0, 1, 2, 1, 3, 2, 2, 3, 4, 3, 5, 4, 4, 5, 6]:\n\t\ttool.add_index(index)\n\treturn tool.commit()\n\n\nfunc _add_grass() -> void:\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tvar pond: Vector3 = WORLD[\"pond\"]\n\tvar pagoda: Vector3 = WORLD[\"pagoda\"]\n\tvar blades := MultiMesh.new()\n\tblades.transform_format = MultiMesh.TRANSFORM_3D\n\tblades.use_colors = true\n\tblades.mesh = _blade()\n\tvar spots: Array[Transform3D] = []\n\tvar tints: Array[Color] = []\n\tvar tries := 0\n\tvar wanted := 18000 if OS.has_feature(\"web\") else 60000\n\twhile spots.size() < wanted and tries < 200000:\n\t\ttries += 1\n\t\t# Thick where you walk and fight, thinner out in the hills.\n\t\tvar reach := 46.0 if tries % 3 else 72.0\n\t\tvar x := _rng.randf_range(-reach, reach)\n\t\tvar z := _rng.randf_range(-reach, minf(reach, 60.0))\n\t\tif path_mask(x, z) > 0.15 or Vector2(x - arena.x, z - arena.z).length() < radius + 0.5:\n\t\t\tcontinue\n\t\tif Vector2(x - pond.x, z - pond.z).length() < 8.0 or Vector2(x - pagoda.x, z - pagoda.z).length() < 10.0:\n\t\t\tcontinue\n\t\tvar basis := Basis(Vector3.UP, _rng.randf() * TAU).scaled(Vector3(1.0, _rng.randf_range(0.55, 1.35), 1.0) * _rng.randf_range(0.8, 1.25))\n\t\tspots.append(Transform3D(basis, Vector3(x, height_at(x, z) - 0.02, z)))\n\t\tvar shade := _rng.randf_range(0.82, 1.18)\n\t\ttints.append(Color(shade * _rng.randf_range(0.95, 1.1), shade, shade * 0.9))\n\tblades.instance_count = spots.size()\n\tfor i in spots.size():\n\t\tblades.set_instance_transform(i, spots[i])\n\t\tblades.set_instance_color(i, tints[i])\n\tgrass = MultiMeshInstance3D.new()\n\tgrass.multimesh = blades\n\tgrass.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF\n\tvar material := ShaderMaterial.new()\n\tmaterial.shader = preload(\"res://grass.gdshader\")\n\tgrass.material_override = material\n\tadd_child(grass)\n\n\nfunc _rock_mesh(seed_value: int) -> ArrayMesh:\n\tvar ball := SphereMesh.new()\n\tball.radius = 1.0\n\tball.height = 2.0\n\tball.radial_segments = 12\n\tball.rings = 7\n\tvar arrays := ball.get_mesh_arrays()\n\tvar points: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]\n\tvar lumps := Look.noise(seed_value, 0.9, 3)\n\tfor i in points.size():\n\t\tvar p := points[i]\n\t\tvar push := 1.0 + lumps.get_noise_3d(p.x * 2.0, p.y * 2.0, p.z * 2.0) * 0.45\n\t\tpoints[i] = Vector3(p.x * push, maxf(p.y, -0.35) * push * 0.75, p.z * push)\n\tarrays[Mesh.ARRAY_VERTEX] = points\n\tarrays[Mesh.ARRAY_NORMAL] = null\n\tarrays[Mesh.ARRAY_TANGENT] = null\n\tvar raw := ArrayMesh.new()\n\traw.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)\n\tvar tool := SurfaceTool.new()\n\ttool.create_from(raw, 0)\n\ttool.deindex()\n\ttool.generate_normals()\n\ttool.generate_tangents()\n\treturn tool.commit()\n\n\nfunc _add_rocks() -> void:\n\tvar shapes: Array[ArrayMesh] = []\n\tfor i in 5:\n\t\tshapes.append(_rock_mesh(40 + i))\n\tvar stone := Look.surface(\"rock\", 14, 0.45)\n\tvar moss := Look.surface(\"moss\", 15, 0.5)\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar radius: float = WORLD[\"arena_radius\"]\n\tfor i in 34:\n\t\tvar x := _rng.randf_range(-62.0, 62.0)\n\t\tvar z := _rng.randf_range(-62.0, 52.0)\n\t\tif path_mask(x, z) > 0.05 or Vector2(x - arena.x, z - arena.z).length() < radius + 3.0:\n\t\t\tcontinue\n\t\tvar size := _rng.randf_range(0.6, 2.6)\n\t\tvar rock := _solid(shapes[i % shapes.size()], moss if i % 3 == 0 else stone, Vector3(x, height_at(x, z) + size * 0.2, z), _box_shape(Vector3(size * 1.4, size, size * 1.4)), Vector3(0, _rng.randf() * TAU, 0))\n\t\trock.scale = Vector3.ONE * size\n\n\nfunc _add_torches() -> void:\n\tvar z := 42.0\n\tvar side := 1.0\n\twhile z > 6.0:\n\t\tvar x := path_x(z) + side * 3.4\n\t\tvar at := Vector3(x, height_at(x, z), z)\n\t\t_solid(_cylinder(0.08, 0.12, 2.2, 8), Look.surface(\"wood\", 16, 1.0), at + Vector3(0, 1.1, 0))\n\t\t_solid(_cylinder(0.32, 0.18, 0.3, 10), Look.surface(\"steel\", 17, 1.0), at + Vector3(0, 2.3, 0))\n\t\tvar fire := Look.fire(0.6)\n\t\tfire.position = at + Vector3(0, 2.55, 0)\n\t\tadd_child(fire)\n\t\tvar light := OmniLight3D.new()\n\t\tlight.light_color = Color(\"#ff8a3d\")\n\t\tlight.light_energy = 1.7\n\t\tlight.omni_range = 8.0\n\t\tlight.position = at + Vector3(0, 2.8, 0)\n\t\tadd_child(light)\n\t\tflames.append(light)\n\t\tz -= 11.0\n\t\tside = -side\n\n\nfunc _add_bonfire() -> void:\n\tvar at: Vector3 = WORLD[\"bonfire\"]\n\tat.y = height_at(at.x, at.z)\n\tvar wood := Look.surface(\"bark\", 18, 1.0)\n\tfor i in 3:\n\t\tvar log_turn := Vector3(0.35, TAU * i / 3.0, PI / 2.0 - 0.3)\n\t\t_solid(_cylinder(0.12, 0.14, 1.6, 8), wood, at + Vector3(0, 0.3, 0), null, log_turn)\n\tfor i in 9:\n\t\tvar angle := TAU * i / 9.0\n\t\tvar pebble := _solid(_rock_mesh(60 + i % 3), Look.surface(\"rock\", 19, 1.0), at + Vector3(cos(angle) * 1.0, 0.08, sin(angle) * 1.0))\n\t\tpebble.scale = Vector3.ONE * 0.28\n\t_solid(_box(Vector3(0.06, 1.5, 0.02)), Look.surface(\"steel\", 20, 1.0), at + Vector3(0, 0.9, 0), null, Vector3(0.2, 0.4, 0.1))\n\tvar fire := Look.fire(1.3)\n\tfire.position = at + Vector3(0, 0.4, 0)\n\tadd_child(fire)\n\tvar smoke := Look.smoke(1.2)\n\tsmoke.position = at + Vector3(0, 1.6, 0)\n\tadd_child(smoke)\n\tvar light := OmniLight3D.new()\n\tlight.light_color = Color(\"#ff8f3f\")\n\tlight.light_energy = 3.2\n\tlight.omni_range = 13.0\n\tlight.shadow_enabled = true\n\tlight.position = at + Vector3(0, 1.2, 0)\n\tadd_child(light)\n\tflames.append(light)\n\n\nfunc _add_air() -> void:\n\tvar arena: Vector3 = WORLD[\"arena\"]\n\tvar embers := Look.embers(Vector3(60, 6, 80), 420)\n\tembers.position = arena + Vector3(0, 2.0, 10)\n\tadd_child(embers)\n\tif RenderingServer.get_current_rendering_method() == \"forward_plus\":\n\t\tfor spot: Vector3 in [arena, arena + Vector3(0, 0, 24), Vector3(WORLD[\"pond\"])]:\n\t\t\tvar mist := FogVolume.new()\n\t\t\tmist.size = Vector3(46, 3.0, 40)\n\t\t\tmist.shape = RenderingServer.FOG_VOLUME_SHAPE_BOX\n\t\t\tvar material := FogMaterial.new()\n\t\t\tmaterial.density = 0.22\n\t\t\tmaterial.albedo = Color(\"#e9c2a6\")\n\t\t\tmaterial.height_falloff = 1.6\n\t\t\tmaterial.edge_fade = 0.6\n\t\t\tmist.material = material\n\t\t\tmist.position = spot + Vector3(0, 0.6, 0)\n\t\t\tadd_child(mist)\n\n\n# ------------------------------------------------------------------ sky, light, graphics\n\nfunc _add_sky_and_light() -> void:\n\tvar sky_material := ProceduralSkyMaterial.new()\n\tsky_material.sky_top_color = WORLD[\"sky_top\"]\n\tsky_material.sky_horizon_color = WORLD[\"horizon\"]\n\tsky_material.sky_curve = 0.12\n\tsky_material.ground_horizon_color = WORLD[\"horizon\"]\n\tsky_material.ground_bottom_color = Color(\"#140d0f\")\n\tsky_material.sun_angle_max = 22.0\n\tsky_material.sun_curve = 0.08\n\tsky_material.energy_multiplier = 1.1\n\tvar sky := Sky.new()\n\tsky.sky_material = sky_material\n\tenvironment = Environment.new()\n\tenvironment.background_mode = Environment.BG_SKY\n\tenvironment.sky = sky\n\tenvironment.ambient_light_source = Environment.AMBIENT_SOURCE_SKY\n\tenvironment.ambient_light_energy = 0.4\n\tenvironment.reflected_light_source = Environment.REFLECTION_SOURCE_SKY\n\tenvironment.tonemap_mode = Environment.TONE_MAPPER_AGX\n\tenvironment.tonemap_exposure = 1.05\n\tenvironment.glow_enabled = true\n\tenvironment.glow_intensity = 0.75\n\tenvironment.glow_bloom = 0.06\n\tenvironment.glow_hdr_threshold = 0.95\n\tenvironment.glow_blend_mode = Environment.GLOW_BLEND_MODE_SOFTLIGHT\n\tenvironment.fog_enabled = true\n\tenvironment.fog_light_color = WORLD[\"fog\"]\n\tenvironment.fog_light_energy = 0.45\n\tenvironment.fog_sun_scatter = 0.3\n\tenvironment.fog_density = 0.0042\n\tenvironment.fog_aerial_perspective = 0.3\n\tenvironment.fog_sky_affect = 0.45\n\tenvironment.fog_height = 1.5\n\tenvironment.fog_height_density = 0.12\n\tenvironment.volumetric_fog_density = 0.016\n\tenvironment.volumetric_fog_albedo = Color(\"#e8b49a\")\n\tenvironment.volumetric_fog_emission = Color(\"#2a0f08\")\n\tenvironment.volumetric_fog_emission_energy = 0.35\n\tenvironment.volumetric_fog_anisotropy = 0.55\n\tenvironment.volumetric_fog_length = 90.0\n\tenvironment.ssao_intensity = 1.7\n\tenvironment.ssao_radius = 1.2\n\tenvironment.adjustment_enabled = true\n\tenvironment.adjustment_contrast = 1.14\n\tenvironment.adjustment_saturation = 1.02\n\tvar world := WorldEnvironment.new()\n\tworld.environment = environment\n\tadd_child(world)\n\tsun = DirectionalLight3D.new()\n\tsun.rotation_degrees = Vector3(-16.0, 148.0, 0.0)\n\tsun.light_color = WORLD[\"sun\"]\n\tsun.light_energy = 2.0\n\tsun.light_angular_distance = 1.2\n\tsun.shadow_enabled = true\n\tsun.shadow_blur = 1.2\n\tsun.directional_shadow_max_distance = 140.0\n\tadd_child(sun)\n\tvar fill := DirectionalLight3D.new()\n\tfill.rotation_degrees = Vector3(-40.0, -25.0, 0.0)\n\tfill.light_color = Color(\"#4a6ab8\")\n\tfill.light_energy = 0.45\n\tfill.sky_mode = DirectionalLight3D.SKY_MODE_LIGHT_ONLY\n\tadd_child(fill)\n\n\n## Low, Medium, High (the default) or Ultra; the heavy effects need the\n## Forward+ renderer (a real graphics card).\nfunc apply_graphics() -> void:\n\tvar forward := RenderingServer.get_current_rendering_method() == \"forward_plus\"\n\tenvironment.ssao_enabled = forward and graphics >= 1\n\tenvironment.ssil_enabled = forward and graphics >= 2\n\tenvironment.volumetric_fog_enabled = forward and graphics >= 1\n\tenvironment.sdfgi_enabled = forward and graphics >= 3\n\tenvironment.ssr_enabled = forward and graphics >= 3\n\tenvironment.glow_enabled = graphics >= 1\n\tsun.directional_shadow_mode = DirectionalLight3D.SHADOW_PARALLEL_4_SPLITS if graphics >= 2 else DirectionalLight3D.SHADOW_PARALLEL_2_SPLITS\n\tvar blades: int = [12000, 30000, -1, -1][graphics]\n\tgrass.multimesh.visible_instance_count = -1 if blades < 0 or blades >= grass.multimesh.instance_count else blades\n\tget_viewport().msaa_3d = [Viewport.MSAA_DISABLED, Viewport.MSAA_2X, Viewport.MSAA_2X, Viewport.MSAA_4X][graphics]\n\tif hud:\n\t\thud.get(\"info\").text = \"Graphics: %s - renderer %s - F2 to change\" % [GRAPHICS[graphics], RenderingServer.get_current_rendering_method()]\n\n\n# ------------------------------------------------------------------ the game\n\nfunc _process(delta: float) -> void:\n\t_clock += delta\n\tfor i in flames.size():\n\t\tvar light := flames[i]\n\t\tif not light.has_meta(\"base\"):\n\t\t\tlight.set_meta(\"base\", light.light_energy)\n\t\tlight.light_energy = float(light.get_meta(\"base\")) * (0.85 + 0.15 * sin(_clock * 11.0 + i * 1.7) + 0.05 * sin(_clock * 23.0 + i))\n\tplayer.set(\"camera_yaw\", rig.get(\"yaw\"))\n\tvar bonfire: Vector3 = WORLD[\"bonfire\"]\n\tvar near := Vector2(player.global_position.x - bonfire.x, player.global_position.z - bonfire.z).length() < 2.8\n\thud.get(\"prompt\").text = \"E  Rest at the bonfire\" if near and not player.call(\"dead\") else \"\"\n\tif near and Input.is_action_just_pressed(\"interact\") and not player.call(\"dead\"):\n\t\tplayer.call(\"refill\")\n\t\tif not won:\n\t\t\t_boss_awake = false\n\t\t\tboss.call(\"reset\")\n\t\t\t_lock(false)\n\t\t\t_on_boss_changed()\n\t\thud.call(\"say\", \"BONFIRE LIT\", Color(\"#f0c27a\"), 2.0)\n\tif Input.is_action_just_pressed(\"lock\"):\n\t\tvar close := player.global_position.distance_to(boss.global_position) < 32.0\n\t\t_lock(not bool(player.get(\"locked\")) and _boss_awake and close and not boss.call(\"is_dead\"))\n\tif bool(player.get(\"locked\")) and boss.call(\"is_dead\"):\n\t\t_lock(false)\n\n\nfunc _lock(on: bool) -> void:\n\tplayer.set(\"locked\", on)\n\trig.set(\"locked\", on)\n\trig.set(\"target\", boss if on else null)\n\n\nfunc _unhandled_input(event: InputEvent) -> void:\n\tif event is InputEventMouseButton and (event as InputEventMouseButton).pressed and Input.mouse_mode != Input.MOUSE_MODE_CAPTURED and not DisplayServer.is_touchscreen_available():\n\t\tInput.mouse_mode = Input.MOUSE_MODE_CAPTURED\n\telif event.is_action_pressed(\"ui_cancel\"):\n\t\tInput.mouse_mode = Input.MOUSE_MODE_VISIBLE\n\telif event.is_action_pressed(\"graphics\"):\n\t\tgraphics = (graphics + 1) % GRAPHICS.size()\n\t\tapply_graphics()\n\t\thud.call(\"say\", \"Graphics: \" + GRAPHICS[graphics], Color(\"#e8dcc8\"), 1.0)\n\telif event.is_action_pressed(\"info\"):\n\t\tvar info: Label = hud.get(\"info\")\n\t\tinfo.visible = not info.visible\n\n\nfunc _on_player_changed() -> void:\n\tvar hp: float = player.get(\"hp\")\n\thud.call(\"show_player\", hp, player.get(\"max_hp\"), player.get(\"stamina\"), player.get(\"max_stamina\"), player.get(\"flasks\"), player.get(\"max_flasks\"))\n\tif hp < _last_hp:\n\t\thud.call(\"flash\")\n\t\trig.call(\"shake\", 0.6)\n\t_last_hp = hp\n\n\nfunc _on_player_died() -> void:\n\t_lock(false)\n\thud.call(\"say\", \"FALLEN\", Color(\"#b3261e\"), 2.5)\n\tawait get_tree().create_timer(4.0).timeout\n\tvar bonfire: Vector3 = WORLD[\"bonfire\"]\n\tplayer.call(\"revive\", Vector3(bonfire.x, height_at(bonfire.x, bonfire.z) + 0.3, bonfire.z + 1.8))\n\t_last_hp = player.get(\"hp\")\n\tif not won:\n\t\t_boss_awake = false\n\t\tboss.call(\"reset\")\n\t\t_on_boss_changed()\n\n\nfunc _on_struck(where: Vector3, heavy: bool) -> void:\n\tsparks.global_position = where\n\tsparks.restart()\n\trig.call(\"shake\", 0.5 if heavy else 0.25)\n\n\nfunc _on_boss_changed() -> void:\n\thud.call(\"show_boss\", BossScript.NAME, boss.get(\"hp\"), boss.get(\"max_hp\"), _boss_awake and not won)\n\n\nfunc _on_boss_woke() -> void:\n\t_boss_awake = true\n\t_on_boss_changed()\n\trig.call(\"shake\", 0.8)\n\n\nfunc _on_boss_defeated() -> void:\n\twon = true\n\t_lock(false)\n\t_on_boss_changed()\n\thud.call(\"say\", \"VICTORY\", Color(\"#f0c27a\"), 4.0)\n\tvar burst := Look.embers(Vector3(8, 3, 8), 300)\n\tadd_child(burst)\n\tburst.global_position = boss.global_position + Vector3(0, 1.5, 0)\n\n\nfunc _on_slammed(where: Vector3, strength: float) -> void:\n\tvar near := clampf(1.0 - player.global_position.distance_to(where) / 18.0, 0.0, 1.0)\n\trig.call(\"shake\", strength * near)\n\tsparks.global_position = where + Vector3(0, 0.3, 0)\n\tsparks.restart()\n\n\n# ------------------------------------------------------------------ controls\n\nfunc _add_inputs() -> void:\n\tvar keys := {\n\t\t\"left\": [KEY_A], \"right\": [KEY_D], \"forward\": [KEY_W], \"back\": [KEY_S],\n\t\t\"run\": [KEY_SHIFT], \"roll\": [KEY_SPACE], \"heal\": [KEY_F], \"lock\": [KEY_Q], \"interact\": [KEY_E],\n\t\t\"graphics\": [KEY_F2], \"info\": [KEY_F3], \"attack\": [KEY_J], \"heavy\": [KEY_K],\n\t\t\"look_left\": [KEY_LEFT], \"look_right\": [KEY_RIGHT], \"look_up\": [KEY_UP], \"look_down\": [KEY_DOWN],\n\t}\n\tvar mouse := {\"attack\": MOUSE_BUTTON_LEFT, \"heavy\": MOUSE_BUTTON_RIGHT, \"lock\": MOUSE_BUTTON_MIDDLE}\n\tvar buttons := {\"roll\": JOY_BUTTON_B, \"attack\": JOY_BUTTON_RIGHT_SHOULDER, \"heavy\": JOY_BUTTON_Y, \"heal\": JOY_BUTTON_X, \"lock\": JOY_BUTTON_RIGHT_STICK, \"interact\": JOY_BUTTON_A, \"run\": JOY_BUTTON_LEFT_STICK}\n\tvar axes := {\n\t\t\"left\": [JOY_AXIS_LEFT_X, -1.0], \"right\": [JOY_AXIS_LEFT_X, 1.0], \"forward\": [JOY_AXIS_LEFT_Y, -1.0], \"back\": [JOY_AXIS_LEFT_Y, 1.0],\n\t\t\"look_left\": [JOY_AXIS_RIGHT_X, -1.0], \"look_right\": [JOY_AXIS_RIGHT_X, 1.0], \"look_up\": [JOY_AXIS_RIGHT_Y, -1.0], \"look_down\": [JOY_AXIS_RIGHT_Y, 1.0],\n\t}\n\tfor action: String in keys:\n\t\tif InputMap.has_action(action):\n\t\t\tcontinue\n\t\tInputMap.add_action(action, 0.2)\n\t\tfor code: Key in keys[action]:\n\t\t\tvar key := InputEventKey.new()\n\t\t\tkey.physical_keycode = code\n\t\t\tInputMap.action_add_event(action, key)\n\t\tif mouse.has(action):\n\t\t\tvar click := InputEventMouseButton.new()\n\t\t\tclick.button_index = mouse[action]\n\t\t\tInputMap.action_add_event(action, click)\n\t\tif buttons.has(action):\n\t\t\tvar button := InputEventJoypadButton.new()\n\t\t\tbutton.button_index = buttons[action]\n\t\t\tInputMap.action_add_event(action, button)\n\t\tif axes.has(action):\n\t\t\tvar stick := InputEventJoypadMotion.new()\n\t\t\tstick.axis = axes[action][0]\n\t\t\tstick.axis_value = axes[action][1]\n\t\t\tInputMap.action_add_event(action, stick)\n","main.tscn":"[gd_scene format=3]\n\n[ext_resource type=\"Script\" path=\"res://main.gd\" id=\"1_main\"]\n\n[node name=\"Main\" type=\"Node3D\"]\nscript = ExtResource(\"1_main\")\n","player.gd":"extends CharacterBody3D\n## The warrior. Moves where the camera looks; run, dodge roll (untouchable in\n## the middle of the roll), light and heavy attacks, a healing flask and\n## lock-on. Every action costs stamina, which only comes back when you stop.\n\nsignal changed\nsignal died\nsignal struck(where: Vector3, heavy: bool)\n\nconst Fighter := preload(\"res://fighter.gd\")\nconst WALK := 3.4\nconst RUN := 6.6\nconst ROLL := 7.8\nconst GRAVITY := 24.0\nconst TURN := 12.0\nconst ACTIONS := {\n\t\"roll\": {\"time\": 0.62, \"stamina\": 22.0, \"safe\": [0.06, 0.42]},\n\t\"light\": {\"time\": 0.62, \"stamina\": 16.0, \"window\": [0.3, 0.46], \"damage\": 26.0, \"reach\": 2.7},\n\t\"heavy\": {\"time\": 1.08, \"stamina\": 32.0, \"window\": [0.52, 0.68], \"damage\": 58.0, \"reach\": 3.1},\n\t\"heal\": {\"time\": 1.15},\n\t\"hit\": {\"time\": 0.5},\n}\n\nvar max_hp := 100.0\nvar hp := 100.0\nvar max_stamina := 100.0\nvar stamina := 100.0\nvar max_flasks := 3\nvar flasks := 3\nvar state := \"move\"\nvar state_time := 0.0\nvar rest := 0.0\nvar facing := 0.0\nvar camera_yaw := 0.0\nvar target: Node3D\nvar locked := false\nvar body: Node3D\nvar _did_hit := false\nvar _healed := false\nvar _roll_dir := Vector3.FORWARD\nvar _speed := 0.0\nvar _clock := 0.0\n\n\nfunc _ready() -> void:\n\tvar shape := CollisionShape3D.new()\n\tvar capsule := CapsuleShape3D.new()\n\tcapsule.radius = 0.36\n\tcapsule.height = 1.8\n\tshape.shape = capsule\n\tshape.position.y = 0.9\n\tadd_child(shape)\n\tbody = Fighter.new()\n\tadd_child(body)\n\tbody.call(\"build\", {\"size\": 1.0, \"armour\": \"steel\", \"cloth\": \"cloth\", \"skin\": \"leather\", \"weapon\": \"sword\", \"glow\": Color(1.0, 0.55, 0.2)})\n\tfloor_snap_length = 0.4\n\n\nfunc dead() -> bool:\n\treturn state == \"dead\"\n\n\nfunc untouchable() -> bool:\n\tif state == \"dead\":\n\t\treturn true\n\tif state != \"roll\":\n\t\treturn false\n\tvar safe: Array = ACTIONS[\"roll\"][\"safe\"]\n\treturn state_time > safe[0] and state_time < safe[1]\n\n\n## Take a hit; false when the roll's i-frames dodged it.\nfunc take_hit(damage: float, from: Vector3) -> bool:\n\tif untouchable():\n\t\treturn false\n\thp = maxf(0.0, hp - damage)\n\tvar away := global_position - from\n\taway.y = 0\n\tvelocity += away.normalized() * 6.0\n\t_start(\"dead\" if hp <= 0.0 else \"hit\")\n\tchanged.emit()\n\tif hp <= 0.0:\n\t\tdied.emit()\n\treturn true\n\n\nfunc revive(at: Vector3) -> void:\n\thp = max_hp\n\tstamina = max_stamina\n\tflasks = max_flasks\n\tglobal_position = at\n\tvelocity = Vector3.ZERO\n\t_start(\"move\")\n\tchanged.emit()\n\n\nfunc refill() -> void:\n\thp = max_hp\n\tflasks = max_flasks\n\tchanged.emit()\n\n\nfunc _start(next: String) -> void:\n\tstate = next\n\tstate_time = 0.0\n\t_did_hit = false\n\t_healed = false\n\n\nfunc _spend(action: String) -> bool:\n\tif stamina <= 0.0:\n\t\treturn false\n\tstamina = maxf(0.0, stamina - float(ACTIONS[action][\"stamina\"]))\n\trest = 0.0\n\tchanged.emit()\n\treturn true\n\n\nfunc forward() -> Vector3:\n\treturn Vector3(-sin(facing), 0, -cos(facing))\n\n\nfunc _physics_process(delta: float) -> void:\n\t_clock += delta\n\tstate_time += delta\n\trest += delta\n\tif not is_on_floor():\n\t\tvelocity.y -= GRAVITY * delta\n\tvar input := Input.get_vector(\"left\", \"right\", \"forward\", \"back\")\n\tvar wish := Vector3(input.x, 0, input.y).rotated(Vector3.UP, camera_yaw)\n\tvar length := ACTIONS.get(state, {}).get(\"time\", 0.0) as float\n\tvar progress := clampf(state_time / length, 0.0, 1.0) if length > 0.0 else 0.0\n\tvar running := false\n\tmatch state:\n\t\t\"move\":\n\t\t\trunning = Input.is_action_pressed(\"run\") and stamina > 1.0 and wish.length() > 0.2\n\t\t\tvar speed := RUN if running else WALK\n\t\t\tif running:\n\t\t\t\tstamina = maxf(0.0, stamina - 14.0 * delta)\n\t\t\t\trest = 0.0\n\t\t\tvelocity.x = move_toward(velocity.x, wish.x * speed, 40.0 * delta)\n\t\t\tvelocity.z = move_toward(velocity.z, wish.z * speed, 40.0 * delta)\n\t\t\t_speed = clampf(Vector2(velocity.x, velocity.z).length() / RUN, 0.0, 1.0)\n\t\t\tif locked and target:\n\t\t\t\tvar to := target.global_position - global_position\n\t\t\t\tfacing = lerp_angle(facing, atan2(-to.x, -to.z), minf(1.0, TURN * delta))\n\t\t\telif wish.length() > 0.1:\n\t\t\t\tfacing = lerp_angle(facing, atan2(-wish.x, -wish.z), minf(1.0, TURN * delta))\n\t\t\tif Input.is_action_just_pressed(\"roll\") and _spend(\"roll\"):\n\t\t\t\t_roll_dir = wish.normalized() if wish.length() > 0.1 else forward()\n\t\t\t\tfacing = atan2(-_roll_dir.x, -_roll_dir.z)\n\t\t\t\t_start(\"roll\")\n\t\t\telif Input.is_action_just_pressed(\"attack\") and _spend(\"light\"):\n\t\t\t\t_start(\"light\")\n\t\t\telif Input.is_action_just_pressed(\"heavy\") and _spend(\"heavy\"):\n\t\t\t\t_start(\"heavy\")\n\t\t\telif Input.is_action_just_pressed(\"heal\") and flasks > 0:\n\t\t\t\t_start(\"heal\")\n\t\t\"roll\":\n\t\t\tvar push := ROLL * (1.0 - progress * 0.55)\n\t\t\tvelocity.x = _roll_dir.x * push\n\t\t\tvelocity.z = _roll_dir.z * push\n\t\t\"light\", \"heavy\":\n\t\t\tvar step := forward() * (2.2 if state_time < 0.25 else 0.0)\n\t\t\tvelocity.x = move_toward(velocity.x, step.x, 30.0 * delta)\n\t\t\tvelocity.z = move_toward(velocity.z, step.z, 30.0 * delta)\n\t\t\t_swing(state)\n\t\t\"heal\":\n\t\t\tvelocity.x = move_toward(velocity.x, wish.x * 1.2, 20.0 * delta)\n\t\t\tvelocity.z = move_toward(velocity.z, wish.z * 1.2, 20.0 * delta)\n\t\t\tif progress > 0.55 and not _healed:\n\t\t\t\t_healed = true\n\t\t\t\tflasks -= 1\n\t\t\t\thp = minf(max_hp, hp + 45.0)\n\t\t\t\tchanged.emit()\n\t\t\"hit\", \"dead\":\n\t\t\tvelocity.x = move_toward(velocity.x, 0.0, 18.0 * delta)\n\t\t\tvelocity.z = move_toward(velocity.z, 0.0, 18.0 * delta)\n\tif state != \"move\" and state != \"dead\" and length > 0.0 and state_time >= length:\n\t\t_start(\"move\")\n\tif rest > 0.75 and state == \"move\" and not running and stamina < max_stamina:\n\t\tstamina = minf(max_stamina, stamina + 42.0 * delta)\n\t\tchanged.emit()\n\tmove_and_slide()\n\tbody.rotation.y = facing\n\tvar shown := \"move\" if state == \"move\" and _speed > 0.05 else (\"idle\" if state == \"move\" else state)\n\tvar dying := clampf(state_time / 1.4, 0.0, 1.0)\n\tbody.call(\"pose\", shown, _clock, dying if state == \"dead\" else progress, _speed)\n\n\nfunc _swing(kind: String) -> void:\n\tvar spec: Dictionary = ACTIONS[kind]\n\tvar window: Array = spec[\"window\"]\n\tif _did_hit or state_time < window[0] or state_time > window[1] or not target:\n\t\treturn\n\tif target.has_method(\"is_dead\") and target.call(\"is_dead\"):\n\t\treturn\n\tvar to := target.global_position - global_position\n\tto.y = 0.0\n\tvar radius: float = target.get(\"radius\") if target.get(\"radius\") != null else 0.8\n\tif to.length() > float(spec[\"reach\"]) + radius:\n\t\treturn\n\tif to.length() > 0.5 and forward().angle_to(to.normalized()) > deg_to_rad(75.0):\n\t\treturn\n\t_did_hit = true\n\ttarget.call(\"take_hit\", float(spec[\"damage\"]), global_position)\n\tstruck.emit(global_position + forward() * 1.4 + Vector3(0, 1.2, 0), kind == \"heavy\")\n","project.godot":"; Godot 4 project made by FCC's game maker (the action-3d starter).\n\nconfig_version=5\n\n[application]\n\nconfig/name=\"Game Name\"\nrun/main_scene=\"res://main.tscn\"\nconfig/features=PackedStringArray(\"4.7\", \"Forward Plus\")\n\n[display]\n\nwindow/size/viewport_width=1600\nwindow/size/viewport_height=900\nwindow/stretch/mode=\"canvas_items\"\nwindow/stretch/aspect=\"expand\"\n\n[input_devices]\n\npointing/emulate_mouse_from_touch=false\n\n[rendering]\n\nrenderer/rendering_method=\"forward_plus\"\nanti_aliasing/quality/msaa_3d=2\nlights_and_shadows/directional_shadow/size=4096\nlights_and_shadows/directional_shadow/soft_shadow_filter_quality=3\nlights_and_shadows/positional_shadow/soft_shadow_filter_quality=3\ntextures/default_filters/anisotropic_filtering_level=3\nenvironment/defaults/default_clear_color=Color(0.05, 0.04, 0.05, 1)\n","terrain.gdshader":"// The ground: grass, a worn dirt path (the vertex colour's red) and rock on\n// the slopes, each from its own texture, mapped by world position.\nshader_type spatial;\n\nuniform sampler2D grass_tex : source_color, filter_linear_mipmap_anisotropic, repeat_enable;\nuniform sampler2D dirt_tex : source_color, filter_linear_mipmap_anisotropic, repeat_enable;\nuniform sampler2D rock_tex : source_color, filter_linear_mipmap_anisotropic, repeat_enable;\nuniform sampler2D bumps : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;\nuniform float scale = 0.11;\n\nvarying vec3 world_pos;\nvarying float slope;\n\nvoid vertex() {\n\tworld_pos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;\n\tslope = 1.0 - clamp((MODEL_MATRIX * vec4(NORMAL, 0.0)).y, 0.0, 1.0);\n}\n\nvoid fragment() {\n\tvec2 uv = world_pos.xz * scale;\n\tvec3 grass = texture(grass_tex, uv).rgb;\n\tvec3 dirt = texture(dirt_tex, uv * 1.4).rgb;\n\tvec3 rock = texture(rock_tex, uv * 0.6).rgb;\n\tfloat path = smoothstep(0.15, 0.85, COLOR.r);\n\tvec3 color = mix(grass, dirt, path);\n\tcolor = mix(color, rock, smoothstep(0.22, 0.45, slope));\n\tALBEDO = color;\n\tROUGHNESS = mix(0.92, 0.8, path);\n\tNORMAL_MAP = texture(bumps, uv * 2.3).rgb;\n\tNORMAL_MAP_DEPTH = 1.2;\n}\n","touch.gd":"extends CanvasLayer\n## Touch controls, shown only on touch screens (a phone or a tablet): a\n## joystick under the left thumb, camera turning with the right thumb, and\n## buttons for light and heavy attacks, roll, flask, lock-on and rest.\n\nconst STICK_RADIUS := 90.0\nconst LOOK_SPEED := 0.006\n# Plain words: the web build has no system fonts for symbols.\nconst BUTTONS := [\n\t[\"attack\", \"HIT\", Vector2(-120, -150), 62.0],\n\t[\"heavy\", \"HEAVY\", Vector2(-250, -110), 50.0],\n\t[\"roll\", \"ROLL\", Vector2(-120, -290), 50.0],\n\t[\"heal\", \"HEAL\", Vector2(-260, -250), 42.0],\n\t[\"lock\", \"LOCK\", Vector2(-380, -150), 40.0],\n\t[\"interact\", \"REST\", Vector2(-380, -280), 36.0],\n]\n\nvar rig: Node3D\nvar _stick_touch := -1\nvar _stick_origin := Vector2.ZERO\nvar _look_touch := -1\nvar _look_last := Vector2.ZERO\nvar _base: Control\nvar _knob: Control\nvar _buttons: Array[TouchScreenButton] = []\n\n\nfunc _ready() -> void:\n\tvisible = DisplayServer.is_touchscreen_available()\n\t_base = _circle(STICK_RADIUS, Color(1, 1, 1, 0.12))\n\t_knob = _circle(STICK_RADIUS * 0.45, Color(1, 1, 1, 0.35))\n\t_base.visible = false\n\t_knob.visible = false\n\tadd_child(_base)\n\tadd_child(_knob)\n\tfor spec: Array in BUTTONS:\n\t\tvar button := TouchScreenButton.new()\n\t\tvar radius: float = spec[3]\n\t\tbutton.texture_normal = _dot(radius, Color(0.08, 0.06, 0.06, 0.55))\n\t\tbutton.texture_pressed = _dot(radius, Color(0.9, 0.45, 0.15, 0.75))\n\t\tvar shape := CircleShape2D.new()\n\t\tshape.radius = radius\n\t\tbutton.shape = shape\n\t\tbutton.shape_centered = true\n\t\tbutton.action = spec[0]\n\t\tbutton.set_meta(\"offset\", spec[2])\n\t\tbutton.set_meta(\"radius\", radius)\n\t\tvar label := Label.new()\n\t\tlabel.text = spec[1]\n\t\tlabel.add_theme_font_size_override(\"font_size\", int(radius * 0.42))\n\t\tlabel.add_theme_color_override(\"font_color\", Color(1, 0.93, 0.82))\n\t\tlabel.size = Vector2(radius * 2.0, radius * 2.0)\n\t\tlabel.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\t\tlabel.vertical_alignment = VERTICAL_ALIGNMENT_CENTER\n\t\tbutton.add_child(label)\n\t\tadd_child(button)\n\t\t_buttons.append(button)\n\tget_viewport().size_changed.connect(_place)\n\t_place()\n\n\nfunc _place() -> void:\n\tvar screen := get_viewport().get_visible_rect().size\n\tfor button in _buttons:\n\t\tvar offset: Vector2 = button.get_meta(\"offset\")\n\t\tvar radius: float = button.get_meta(\"radius\")\n\t\tbutton.position = screen + offset - Vector2(radius, radius)\n\n\nfunc _circle(radius: float, color: Color) -> Control:\n\tvar holder := TextureRect.new()\n\tholder.texture = _dot(radius, color)\n\tholder.size = Vector2(radius * 2.0, radius * 2.0)\n\tholder.mouse_filter = Control.MOUSE_FILTER_IGNORE\n\treturn holder\n\n\nfunc _dot(radius: float, color: Color) -> GradientTexture2D:\n\tvar dot := GradientTexture2D.new()\n\tdot.width = int(radius * 2.0)\n\tdot.height = int(radius * 2.0)\n\tdot.fill = GradientTexture2D.FILL_RADIAL\n\tdot.fill_from = Vector2(0.5, 0.5)\n\tdot.fill_to = Vector2(0.5, 0.0)\n\tvar gradient := Gradient.new()\n\tgradient.offsets = PackedFloat32Array([0.0, 0.92, 1.0])\n\tgradient.colors = PackedColorArray([color, color, Color(color.r, color.g, color.b, 0.0)])\n\tdot.gradient = gradient\n\treturn dot\n\n\nfunc _on_button(at: Vector2) -> bool:\n\tfor button in _buttons:\n\t\tvar radius: float = button.get_meta(\"radius\")\n\t\tif at.distance_to(button.position + Vector2(radius, radius)) < radius * 1.15:\n\t\t\treturn true\n\treturn false\n\n\nfunc _input(event: InputEvent) -> void:\n\tif not visible:\n\t\treturn\n\tvar screen := get_viewport().get_visible_rect().size\n\tif event is InputEventScreenTouch:\n\t\tvar touch := event as InputEventScreenTouch\n\t\tif touch.pressed:\n\t\t\tif touch.position.x < screen.x * 0.4 and _stick_touch == -1:\n\t\t\t\t_stick_touch = touch.index\n\t\t\t\t_stick_origin = touch.position\n\t\t\t\t_base.position = touch.position - Vector2(STICK_RADIUS, STICK_RADIUS)\n\t\t\t\t_knob.position = touch.position - _knob.size * 0.5\n\t\t\t\t_base.visible = true\n\t\t\t\t_knob.visible = true\n\t\t\telif touch.position.x >= screen.x * 0.4 and _look_touch == -1 and not _on_button(touch.position):\n\t\t\t\t_look_touch = touch.index\n\t\t\t\t_look_last = touch.position\n\t\telse:\n\t\t\tif touch.index == _stick_touch:\n\t\t\t\t_stick_touch = -1\n\t\t\t\t_base.visible = false\n\t\t\t\t_knob.visible = false\n\t\t\t\tfor action: String in [\"left\", \"right\", \"forward\", \"back\"]:\n\t\t\t\t\tInput.action_release(action)\n\t\t\telif touch.index == _look_touch:\n\t\t\t\t_look_touch = -1\n\telif event is InputEventScreenDrag:\n\t\tvar drag := event as InputEventScreenDrag\n\t\tif drag.index == _stick_touch:\n\t\t\tvar offset := (drag.position - _stick_origin).limit_length(STICK_RADIUS)\n\t\t\t_knob.position = _stick_origin + offset - _knob.size * 0.5\n\t\t\tvar stick := offset / STICK_RADIUS\n\t\t\t_press(\"right\", stick.x)\n\t\t\t_press(\"left\", -stick.x)\n\t\t\t_press(\"back\", stick.y)\n\t\t\t_press(\"forward\", -stick.y)\n\t\t\tif stick.length() > 0.92:\n\t\t\t\tInput.action_press(\"run\")\n\t\t\telse:\n\t\t\t\tInput.action_release(\"run\")\n\t\telif drag.index == _look_touch and rig and not bool(rig.get(\"locked\")):\n\t\t\tvar moved := drag.position - _look_last\n\t\t\t_look_last = drag.position\n\t\t\trig.set(\"yaw\", float(rig.get(\"yaw\")) - moved.x * LOOK_SPEED)\n\t\t\trig.set(\"pitch\", clampf(float(rig.get(\"pitch\")) - moved.y * LOOK_SPEED, -1.1, 0.35))\n\n\nfunc _press(action: String, strength: float) -> void:\n\tif strength > 0.15:\n\t\tInput.action_press(action, clampf(strength, 0.0, 1.0))\n\telse:\n\t\tInput.action_release(action)\n","vignette.gdshader":"// A soft dark edge on the screen, and a red flash when you're hit.\nshader_type canvas_item;\n\nuniform float strength = 0.6;\nuniform float flash = 0.0;\n\nvoid fragment() {\n\tvec2 p = (UV - 0.5) * vec2(1.0, 0.82);\n\tfloat edge = smoothstep(0.32, 0.86, length(p));\n\tCOLOR = vec4(mix(vec3(0.0), vec3(0.55, 0.02, 0.0), flash), edge * strength + flash * 0.3);\n}\n","water.gdshader":"// Still dark water: slow ripples, a sky sheen at grazing angles.\nshader_type spatial;\nrender_mode cull_back, specular_schlick_ggx;\n\nuniform vec3 deep : source_color = vec3(0.01, 0.04, 0.05);\nuniform vec3 sheen : source_color = vec3(0.45, 0.32, 0.25);\n\nvoid vertex() {\n\tVERTEX.y += sin(VERTEX.x * 0.9 + TIME * 1.1) * 0.025 + cos(VERTEX.z * 0.7 + TIME * 0.8) * 0.025;\n}\n\nvoid fragment() {\n\tvec2 w = UV * 24.0 + vec2(TIME * 0.12, TIME * 0.07);\n\tvec3 ripple = normalize(vec3(sin(w.x * 2.1 + TIME) * 0.08 + sin(w.y * 1.3) * 0.05, 1.0, cos(w.y * 2.4 - TIME) * 0.08));\n\tNORMAL = normalize((VIEW_MATRIX * vec4(ripple, 0.0)).xyz);\n\tfloat fresnel = pow(1.0 - clamp(dot(NORMAL, VIEW), 0.0, 1.0), 4.0);\n\tALBEDO = mix(deep, sheen, fresnel * 0.6);\n\tROUGHNESS = 0.04;\n\tSPECULAR = 0.7;\n\tALPHA = 0.9;\n}\n"}},"third-person-3d":{"about":"A 3D third-person game: a camera on a spring arm, walk, run and jump, orbs to collect, sun, sky and shadows.","files":{"export_presets.cfg":"[preset.0]\n\nname=\"Windows Desktop\"\nplatform=\"Windows Desktop\"\nrunnable=true\nexport_filter=\"all_resources\"\ninclude_filter=\"\"\nexclude_filter=\"\"\nexport_path=\"build/game.exe\"\n\n[preset.0.options]\n\nbinary_format/embed_pck=true\n","main.gd":"extends Node3D\n## A low-poly 3D world built in code: sun and sky, ground, crates, ramps,\n## floating orbs to collect, and the player. Change the look in LOOK.\n\nconst LOOK := {\n\t\"sky_top\": Color(\"#3f7fd6\"),\n\t\"sky_horizon\": Color(\"#bfe3ff\"),\n\t\"ground\": Color(\"#6dbb5a\"),\n\t\"crate\": Color(\"#c98b4f\"),\n\t\"orb\": Color(\"#ffd447\"),\n}\nconst ORBS := 12\n\nvar player: CharacterBody3D\nvar hud: Label\nvar collected := 0\n\n\nfunc _ready() -> void:\n\t_add_inputs()\n\t_add_world()\n\tplayer = preload(\"res://player.gd\").new()\n\tplayer.position = Vector3(0, 1, 0)\n\tadd_child(player)\n\tvar rng := RandomNumberGenerator.new()\n\trng.seed = 7\n\tfor i in 18:\n\t\tvar size := rng.randf_range(1.0, 3.0)\n\t\t_add_block(Vector3(rng.randf_range(-24, 24), size / 2.0, rng.randf_range(-24, 24)), Vector3.ONE * size, LOOK[\"crate\"])\n\t_add_block(Vector3(8, 0.5, -6), Vector3(6, 1, 4), LOOK[\"crate\"], deg_to_rad(-15))\n\tfor i in ORBS:\n\t\tvar angle := TAU * i / ORBS\n\t\t_add_orb(Vector3(cos(angle) * 14.0, 1.2 + (i % 3) * 1.5, sin(angle) * 14.0))\n\tvar layer := CanvasLayer.new()\n\thud = Label.new()\n\thud.position = Vector2(16, 12)\n\thud.add_theme_font_size_override(\"font_size\", 22)\n\thud.add_theme_color_override(\"font_outline_color\", Color.BLACK)\n\thud.add_theme_constant_override(\"outline_size\", 6)\n\tlayer.add_child(hud)\n\tadd_child(layer)\n\tvar touch: CanvasLayer = preload(\"res://touch.gd\").new()\n\ttouch.set(\"player\", player)\n\tadd_child(touch)\n\t_update_hud()\n\n\nfunc collect() -> void:\n\tcollected += 1\n\t_update_hud()\n\n\nfunc _update_hud() -> void:\n\tvar touch := DisplayServer.is_touchscreen_available()\n\tvar help := \"left thumb move, right thumb look, JUMP\" if touch else \"WASD move, mouse look, Space jump, Shift run\"\n\thud.text = \"Orbs: %d / %d   (%s)\" % [collected, ORBS, help]\n\tif collected == ORBS:\n\t\thud.text = \"All orbs found! %s to play again.\" % (\"Tap AGAIN\" if touch else \"Press R\")\n\n\nfunc _unhandled_input(event: InputEvent) -> void:\n\tif event.is_action_pressed(\"restart\"):\n\t\tget_tree().reload_current_scene()\n\n\nfunc _add_world() -> void:\n\tvar sky_material := ProceduralSkyMaterial.new()\n\tsky_material.sky_top_color = LOOK[\"sky_top\"]\n\tsky_material.sky_horizon_color = LOOK[\"sky_horizon\"]\n\tsky_material.ground_horizon_color = LOOK[\"sky_horizon\"]\n\tvar sky := Sky.new()\n\tsky.sky_material = sky_material\n\tvar environment := Environment.new()\n\tenvironment.background_mode = Environment.BG_SKY\n\tenvironment.sky = sky\n\tenvironment.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR\n\tenvironment.ambient_light_color = LOOK[\"sky_horizon\"]\n\tenvironment.ambient_light_energy = 0.35\n\tenvironment.tonemap_mode = Environment.TONE_MAPPER_FILMIC\n\t# Distance haze: light, so near colours stay true.\n\tenvironment.fog_enabled = true\n\tenvironment.fog_mode = Environment.FOG_MODE_DEPTH\n\tenvironment.fog_light_color = LOOK[\"sky_horizon\"]\n\tenvironment.fog_depth_begin = 25.0\n\tenvironment.fog_depth_end = 90.0\n\tenvironment.fog_sky_affect = 0.2\n\tvar world := WorldEnvironment.new()\n\tworld.environment = environment\n\tadd_child(world)\n\tvar sun := DirectionalLight3D.new()\n\tsun.rotation_degrees = Vector3(-50, -35, 0)\n\tsun.shadow_enabled = true\n\tsun.light_energy = 0.9\n\tadd_child(sun)\n\t_add_block(Vector3(0, -0.5, 0), Vector3(60, 1, 60), LOOK[\"ground\"])\n\n\nfunc _material(color: Color) -> StandardMaterial3D:\n\tvar material := StandardMaterial3D.new()\n\tmaterial.albedo_color = color\n\tmaterial.roughness = 0.85\n\treturn material\n\n\nfunc _add_block(at: Vector3, size: Vector3, color: Color, tilt := 0.0) -> void:\n\tvar body := StaticBody3D.new()\n\tbody.position = at\n\tbody.rotation.z = tilt\n\tvar mesh := MeshInstance3D.new()\n\tvar box := BoxMesh.new()\n\tbox.size = size\n\tbox.material = _material(color)\n\tmesh.mesh = box\n\tbody.add_child(mesh)\n\tvar shape := CollisionShape3D.new()\n\tvar box_shape := BoxShape3D.new()\n\tbox_shape.size = size\n\tshape.shape = box_shape\n\tbody.add_child(shape)\n\tadd_child(body)\n\n\nfunc _add_orb(at: Vector3) -> void:\n\tvar orb := Area3D.new()\n\torb.position = at\n\tvar mesh := MeshInstance3D.new()\n\tvar sphere := SphereMesh.new()\n\tsphere.radius = 0.35\n\tsphere.height = 0.7\n\tvar glow := _material(LOOK[\"orb\"])\n\tglow.emission_enabled = true\n\tglow.emission = LOOK[\"orb\"]\n\tglow.emission_energy_multiplier = 1.5\n\tsphere.material = glow\n\tmesh.mesh = sphere\n\torb.add_child(mesh)\n\tvar shape := CollisionShape3D.new()\n\tvar sphere_shape := SphereShape3D.new()\n\tsphere_shape.radius = 0.6\n\tshape.shape = sphere_shape\n\torb.add_child(shape)\n\torb.body_entered.connect(func(body: Node) -> void:\n\t\tif body == player:\n\t\t\tcollect()\n\t\t\torb.queue_free())\n\tadd_child(orb)\n\tvar bob := orb.create_tween().set_loops()\n\tbob.tween_property(orb, \"position:y\", at.y + 0.4, 0.8).set_trans(Tween.TRANS_SINE)\n\tbob.tween_property(orb, \"position:y\", at.y, 0.8).set_trans(Tween.TRANS_SINE)\n\n\nfunc _add_inputs() -> void:\n\tvar keys := {\n\t\t\"left\": [KEY_A, KEY_LEFT],\n\t\t\"right\": [KEY_D, KEY_RIGHT],\n\t\t\"forward\": [KEY_W, KEY_UP],\n\t\t\"back\": [KEY_S, KEY_DOWN],\n\t\t\"jump\": [KEY_SPACE],\n\t\t\"run\": [KEY_SHIFT],\n\t\t\"restart\": [KEY_R],\n\t}\n\tfor action: String in keys:\n\t\tif InputMap.has_action(action):\n\t\t\tcontinue\n\t\tInputMap.add_action(action)\n\t\tfor code: Key in keys[action]:\n\t\t\tvar key := InputEventKey.new()\n\t\t\tkey.physical_keycode = code\n\t\t\tInputMap.action_add_event(action, key)\n","main.tscn":"[gd_scene format=3]\n\n[ext_resource type=\"Script\" path=\"res://main.gd\" id=\"1_main\"]\n\n[node name=\"Main\" type=\"Node3D\"]\nscript = ExtResource(\"1_main\")\n","player.gd":"extends CharacterBody3D\n## A third-person character: the camera orbits with the mouse on a spring\n## arm (it pulls in when a wall is in the way); the body turns to face\n## where it walks, leans into turns and squashes on landing.\n\nconst WALK := 5.0\nconst RUN := 9.0\nconst JUMP := 6.5\nconst GRAVITY := 18.0\nconst TURN := 10.0\nconst MOUSE := 0.003\n\nvar pivot: Node3D\nvar arm: SpringArm3D\nvar body: Node3D\n\n\nfunc _ready() -> void:\n\tvar shape := CollisionShape3D.new()\n\tvar capsule := CapsuleShape3D.new()\n\tcapsule.radius = 0.4\n\tcapsule.height = 1.6\n\tshape.shape = capsule\n\tshape.position.y = 0.8\n\tadd_child(shape)\n\tbody = Node3D.new()\n\tadd_child(body)\n\tvar mesh := MeshInstance3D.new()\n\tvar capsule_mesh := CapsuleMesh.new()\n\tcapsule_mesh.radius = 0.4\n\tcapsule_mesh.height = 1.6\n\tvar material := StandardMaterial3D.new()\n\tmaterial.albedo_color = Color(\"#e8584f\")\n\tcapsule_mesh.material = material\n\tmesh.mesh = capsule_mesh\n\tmesh.position.y = 0.8\n\tbody.add_child(mesh)\n\tvar nose := MeshInstance3D.new()\n\tvar box := BoxMesh.new()\n\tbox.size = Vector3(0.5, 0.18, 0.25)\n\tnose.mesh = box\n\tnose.position = Vector3(0, 1.2, -0.4)\n\tbody.add_child(nose)\n\tpivot = Node3D.new()\n\tpivot.position.y = 1.4\n\tadd_child(pivot)\n\tarm = SpringArm3D.new()\n\tarm.spring_length = 5.0\n\tarm.rotation.x = deg_to_rad(-20)\n\tarm.add_excluded_object(get_rid())\n\tpivot.add_child(arm)\n\tvar camera := Camera3D.new()\n\tarm.add_child(camera)\n\t# The mouse turns the camera on a computer; a phone uses touch.gd instead.\n\tif DisplayServer.get_name() != \"headless\" and not DisplayServer.is_touchscreen_available():\n\t\tInput.mouse_mode = Input.MOUSE_MODE_CAPTURED\n\n\n## Turn the camera (radians): from the mouse, or the right thumb on a phone.\nfunc look(turn: Vector2) -> void:\n\tpivot.rotation.y -= turn.x\n\tarm.rotation.x = clampf(arm.rotation.x - turn.y, deg_to_rad(-70), deg_to_rad(20))\n\n\nfunc _unhandled_input(event: InputEvent) -> void:\n\tif event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:\n\t\tlook(event.relative * MOUSE)\n\tif event is InputEventKey and event.keycode == KEY_ESCAPE:\n\t\tInput.mouse_mode = Input.MOUSE_MODE_VISIBLE\n\tif event is InputEventMouseButton and event.pressed and not DisplayServer.is_touchscreen_available():\n\t\tInput.mouse_mode = Input.MOUSE_MODE_CAPTURED\n\n\nfunc _physics_process(delta: float) -> void:\n\tvar was_on_floor := is_on_floor()\n\tif not is_on_floor():\n\t\tvelocity.y -= GRAVITY * delta\n\tif Input.is_action_just_pressed(\"jump\") and is_on_floor():\n\t\tvelocity.y = JUMP\n\tvar input := Input.get_vector(\"left\", \"right\", \"forward\", \"back\")\n\tvar direction := (pivot.global_basis * Vector3(input.x, 0, input.y))\n\tdirection.y = 0.0\n\tdirection = direction.normalized()\n\tvar speed := RUN if Input.is_action_pressed(\"run\") else WALK\n\tvelocity.x = move_toward(velocity.x, direction.x * speed, 40.0 * delta)\n\tvelocity.z = move_toward(velocity.z, direction.z * speed, 40.0 * delta)\n\tif direction.length() > 0.1:\n\t\tvar target := atan2(-direction.x, -direction.z)\n\t\tbody.rotation.y = lerp_angle(body.rotation.y, target, TURN * delta)\n\tbody.rotation.z = lerpf(body.rotation.z, -input.x * 0.12, 8.0 * delta)\n\tmove_and_slide()\n\tif is_on_floor() and not was_on_floor:\n\t\tbody.scale = Vector3(1.15, 0.85, 1.15)\n\tbody.scale = body.scale.lerp(Vector3.ONE, 10.0 * delta)\n","project.godot":"; Godot 4 project made by FCC's game maker (the third-person-3d starter).\n\nconfig_version=5\n\n[application]\n\nconfig/name=\"Game Name\"\nrun/main_scene=\"res://main.tscn\"\nconfig/features=PackedStringArray(\"4.7\")\n\n[display]\n\nwindow/size/viewport_width=1280\nwindow/size/viewport_height=720\n\n[rendering]\n\nanti_aliasing/quality/msaa_3d=2\n\n[input_devices]\n\npointing/emulate_mouse_from_touch=false\n","touch.gd":"extends CanvasLayer\n## Touch controls, shown only on touch screens (a phone or a tablet): a\n## joystick under the left thumb (push it far to run), camera turning with\n## the right thumb, and buttons to jump and to play again.\n\nconst STICK_RADIUS := 90.0\nconst LOOK_SPEED := 0.006\n# Plain words: the web build has no system fonts for symbols.\nconst BUTTONS := [\n\t[\"jump\", \"JUMP\", Vector2(-130, -150), 64.0],\n\t[\"restart\", \"AGAIN\", Vector2(-110, -320), 38.0],\n]\n\nvar player: Node3D\nvar _stick_touch := -1\nvar _stick_origin := Vector2.ZERO\nvar _look_touch := -1\nvar _look_last := Vector2.ZERO\nvar _base: Control\nvar _knob: Control\nvar _buttons: Array[TouchScreenButton] = []\n\n\nfunc _ready() -> void:\n\tvisible = DisplayServer.is_touchscreen_available()\n\t_base = _circle(STICK_RADIUS, Color(1, 1, 1, 0.12))\n\t_knob = _circle(STICK_RADIUS * 0.45, Color(1, 1, 1, 0.35))\n\t_base.visible = false\n\t_knob.visible = false\n\tadd_child(_base)\n\tadd_child(_knob)\n\tfor spec: Array in BUTTONS:\n\t\tvar button := TouchScreenButton.new()\n\t\tvar radius: float = spec[3]\n\t\tbutton.texture_normal = _dot(radius, Color(0.08, 0.06, 0.06, 0.55))\n\t\tbutton.texture_pressed = _dot(radius, Color(0.9, 0.45, 0.15, 0.75))\n\t\tvar shape := CircleShape2D.new()\n\t\tshape.radius = radius\n\t\tbutton.shape = shape\n\t\tbutton.shape_centered = true\n\t\tbutton.action = spec[0]\n\t\tbutton.set_meta(\"offset\", spec[2])\n\t\tbutton.set_meta(\"radius\", radius)\n\t\tvar label := Label.new()\n\t\tlabel.text = spec[1]\n\t\tlabel.add_theme_font_size_override(\"font_size\", int(radius * 0.42))\n\t\tlabel.add_theme_color_override(\"font_color\", Color(1, 0.93, 0.82))\n\t\tlabel.size = Vector2(radius * 2.0, radius * 2.0)\n\t\tlabel.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\t\tlabel.vertical_alignment = VERTICAL_ALIGNMENT_CENTER\n\t\tbutton.add_child(label)\n\t\tadd_child(button)\n\t\t_buttons.append(button)\n\tget_viewport().size_changed.connect(_place)\n\t_place()\n\n\nfunc _place() -> void:\n\tvar screen := get_viewport().get_visible_rect().size\n\tfor button in _buttons:\n\t\tvar offset: Vector2 = button.get_meta(\"offset\")\n\t\tvar radius: float = button.get_meta(\"radius\")\n\t\tbutton.position = screen + offset - Vector2(radius, radius)\n\n\nfunc _circle(radius: float, color: Color) -> Control:\n\tvar holder := TextureRect.new()\n\tholder.texture = _dot(radius, color)\n\tholder.size = Vector2(radius * 2.0, radius * 2.0)\n\tholder.mouse_filter = Control.MOUSE_FILTER_IGNORE\n\treturn holder\n\n\nfunc _dot(radius: float, color: Color) -> GradientTexture2D:\n\tvar dot := GradientTexture2D.new()\n\tdot.width = int(radius * 2.0)\n\tdot.height = int(radius * 2.0)\n\tdot.fill = GradientTexture2D.FILL_RADIAL\n\tdot.fill_from = Vector2(0.5, 0.5)\n\tdot.fill_to = Vector2(0.5, 0.0)\n\tvar gradient := Gradient.new()\n\tgradient.offsets = PackedFloat32Array([0.0, 0.92, 1.0])\n\tgradient.colors = PackedColorArray([color, color, Color(color.r, color.g, color.b, 0.0)])\n\tdot.gradient = gradient\n\treturn dot\n\n\nfunc _on_button(at: Vector2) -> bool:\n\tfor button in _buttons:\n\t\tvar radius: float = button.get_meta(\"radius\")\n\t\tif at.distance_to(button.position + Vector2(radius, radius)) < radius * 1.15:\n\t\t\treturn true\n\treturn false\n\n\nfunc _input(event: InputEvent) -> void:\n\tif not visible:\n\t\treturn\n\tvar screen := get_viewport().get_visible_rect().size\n\tif event is InputEventScreenTouch:\n\t\tvar touch := event as InputEventScreenTouch\n\t\tif touch.pressed:\n\t\t\tif touch.position.x < screen.x * 0.4 and _stick_touch == -1:\n\t\t\t\t_stick_touch = touch.index\n\t\t\t\t_stick_origin = touch.position\n\t\t\t\t_base.position = touch.position - Vector2(STICK_RADIUS, STICK_RADIUS)\n\t\t\t\t_knob.position = touch.position - _knob.size * 0.5\n\t\t\t\t_base.visible = true\n\t\t\t\t_knob.visible = true\n\t\t\telif touch.position.x >= screen.x * 0.4 and _look_touch == -1 and not _on_button(touch.position):\n\t\t\t\t_look_touch = touch.index\n\t\t\t\t_look_last = touch.position\n\t\telse:\n\t\t\tif touch.index == _stick_touch:\n\t\t\t\t_stick_touch = -1\n\t\t\t\t_base.visible = false\n\t\t\t\t_knob.visible = false\n\t\t\t\tfor action: String in [\"left\", \"right\", \"forward\", \"back\"]:\n\t\t\t\t\tInput.action_release(action)\n\t\t\telif touch.index == _look_touch:\n\t\t\t\t_look_touch = -1\n\telif event is InputEventScreenDrag:\n\t\tvar drag := event as InputEventScreenDrag\n\t\tif drag.index == _stick_touch:\n\t\t\tvar offset := (drag.position - _stick_origin).limit_length(STICK_RADIUS)\n\t\t\t_knob.position = _stick_origin + offset - _knob.size * 0.5\n\t\t\tvar stick := offset / STICK_RADIUS\n\t\t\t_press(\"right\", stick.x)\n\t\t\t_press(\"left\", -stick.x)\n\t\t\t_press(\"back\", stick.y)\n\t\t\t_press(\"forward\", -stick.y)\n\t\t\tif stick.length() > 0.92:\n\t\t\t\tInput.action_press(\"run\")\n\t\t\telse:\n\t\t\t\tInput.action_release(\"run\")\n\t\telif drag.index == _look_touch and player:\n\t\t\tvar moved := drag.position - _look_last\n\t\t\t_look_last = drag.position\n\t\t\tplayer.call(\"look\", moved * LOOK_SPEED)\n\n\nfunc _press(action: String, strength: float) -> void:\n\tif strength > 0.15:\n\t\tInput.action_press(action, clampf(strength, 0.0, 1.0))\n\telse:\n\t\tInput.action_release(action)\n"}}};
export const GODOT_PROBE = {"probe.gd":"extends Node3D\n## FCC's Godot probe. It tries the engine's parts one at a time on the device\n## it runs on (FCC Phone's Godot box, or a PC) and sorts them into works,\n## limited, missing and blocked (switched off on purpose by FCC's box). It\n## shows the list on screen and prints it once as one line:\n## FCC_PROBE {\"version\": ..., \"items\": [{\"group\", \"name\", \"status\", \"detail\"}]}\n## Every test is short and can't hang: nothing waits longer than a few seconds.\n\nconst CLASSES := {\n\t\"3D\": [\"CSGBox3D\", \"GridMap\", \"GPUParticles3D\", \"CPUParticles3D\", \"MultiMeshInstance3D\", \"Skeleton3D\", \"SoftBody3D\", \"VehicleBody3D\", \"NavigationAgent3D\", \"Path3D\", \"Decal\", \"ReflectionProbe\", \"LightmapGI\", \"VoxelGI\", \"FogVolume\", \"OccluderInstance3D\"],\n\t\"2D\": [\"TileMapLayer\", \"GPUParticles2D\", \"Line2D\", \"Polygon2D\", \"Skeleton2D\", \"NavigationAgent2D\", \"Parallax2D\", \"PointLight2D\"],\n\t\"Sound\": [\"AudioStreamOggVorbis\", \"AudioStreamMP3\", \"AudioStreamWAV\", \"AudioStreamGenerator\", \"AudioStreamMicrophone\", \"AudioEffectReverb\"],\n\t\"Video\": [\"VideoStreamTheora\"],\n\t\"Code\": [\"GDScript\", \"Expression\", \"RegEx\", \"JSON\", \"Crypto\", \"ZIPReader\", \"ZIPPacker\", \"AStar3D\", \"FastNoiseLite\"],\n\t\"Network\": [\"HTTPRequest\", \"WebSocketPeer\", \"WebRTCPeerConnection\", \"ENetConnection\", \"UPNP\", \"MultiplayerSynchronizer\"],\n\t\"XR\": [\"WebXRInterface\", \"OpenXRInterface\"],\n}\nconst FORWARD_ONLY := \"SDFGI, VoxelGI, volumetric fog, screen-space reflections, SSAO and SSIL\"\n\nvar items: Array[Dictionary] = []\nvar _list: Label\nvar _ball: RigidBody3D\n\n\nfunc _ready() -> void:\n\t_build_scene()\n\t_build_screen()\n\t_say(\"Testing Godot on this device...\")\n\tawait get_tree().process_frame\n\t_engine()\n\t_classes()\n\t_threads()\n\t_memory()\n\t_files()\n\t_data()\n\t_images()\n\t_text()\n\t_controls()\n\tawait _physics()\n\tawait _drawing()\n\t_sound()\n\tawait _network()\n\t_bridge()\n\t_report()\n\n\nfunc _add(group: String, title: String, status: String, detail: String) -> void:\n\titems.append({\"group\": group, \"name\": title, \"status\": status, \"detail\": detail})\n\n\nfunc _say(text: String) -> void:\n\tif _list:\n\t\t_list.text = text\n\n\nfunc _web() -> bool:\n\treturn OS.has_feature(\"web\")\n\n\nfunc _build_scene() -> void:\n\tvar sun := DirectionalLight3D.new()\n\tsun.rotation_degrees = Vector3(-50, 30, 0)\n\tsun.shadow_enabled = true\n\tadd_child(sun)\n\tvar world := WorldEnvironment.new()\n\tvar environment := Environment.new()\n\tenvironment.background_mode = Environment.BG_COLOR\n\tenvironment.background_color = Color(0.09, 0.11, 0.16)\n\tenvironment.glow_enabled = true\n\tenvironment.tonemap_mode = Environment.TONE_MAPPER_FILMIC\n\tworld.environment = environment\n\tadd_child(world)\n\tvar camera := Camera3D.new()\n\tcamera.position = Vector3(0, 3.5, 8)\n\tcamera.rotation_degrees = Vector3(-18, 0, 0)\n\tadd_child(camera)\n\tvar floor_body := StaticBody3D.new()\n\tvar floor_shape := CollisionShape3D.new()\n\tvar box := BoxShape3D.new()\n\tbox.size = Vector3(20, 1, 20)\n\tfloor_shape.shape = box\n\tfloor_body.add_child(floor_shape)\n\tvar floor_mesh := MeshInstance3D.new()\n\tvar plane := BoxMesh.new()\n\tplane.size = Vector3(20, 1, 20)\n\tfloor_mesh.mesh = plane\n\tvar ground := StandardMaterial3D.new()\n\tground.albedo_color = Color(0.25, 0.35, 0.3)\n\tfloor_mesh.material_override = ground\n\tfloor_body.add_child(floor_mesh)\n\tfloor_body.position.y = -0.5\n\tadd_child(floor_body)\n\t_ball = RigidBody3D.new()\n\tvar ball_shape := CollisionShape3D.new()\n\tvar sphere := SphereShape3D.new()\n\tsphere.radius = 0.5\n\tball_shape.shape = sphere\n\t_ball.add_child(ball_shape)\n\tvar ball_mesh := MeshInstance3D.new()\n\tvar round_mesh := SphereMesh.new()\n\tround_mesh.radius = 0.5\n\tround_mesh.height = 1.0\n\tball_mesh.mesh = round_mesh\n\tvar shiny := ShaderMaterial.new()\n\tvar shader := Shader.new()\n\tshader.code = \"shader_type spatial;\\nvoid fragment() {\\n\\tALBEDO = vec3(0.9, 0.5 + 0.4 * sin(TIME * 3.0), 0.2);\\n\\tROUGHNESS = 0.3;\\n}\\n\"\n\tshiny.shader = shader\n\tball_mesh.material_override = shiny\n\t_ball.add_child(ball_mesh)\n\t_ball.position = Vector3(0, 4, 0)\n\tadd_child(_ball)\n\tvar sparks := GPUParticles3D.new()\n\tsparks.amount = 64\n\tvar process := ParticleProcessMaterial.new()\n\tprocess.direction = Vector3(0, 1, 0)\n\tprocess.initial_velocity_min = 1.0\n\tprocess.initial_velocity_max = 2.0\n\tsparks.process_material = process\n\tvar dot := SphereMesh.new()\n\tdot.radius = 0.05\n\tdot.height = 0.1\n\tsparks.draw_pass_1 = dot\n\tsparks.position = Vector3(2, 0.5, 0)\n\tadd_child(sparks)\n\n\nfunc _build_screen() -> void:\n\tvar layer := CanvasLayer.new()\n\tadd_child(layer)\n\tvar scroll := ScrollContainer.new()\n\tscroll.set_anchors_preset(Control.PRESET_FULL_RECT)\n\tscroll.offset_left = 24\n\tscroll.offset_top = 24\n\tscroll.offset_right = -24\n\tscroll.offset_bottom = -24\n\tlayer.add_child(scroll)\n\t_list = Label.new()\n\t_list.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART\n\t_list.custom_minimum_size = Vector2(600, 0)\n\t_list.add_theme_font_size_override(\"font_size\", 22)\n\t_list.add_theme_color_override(\"font_outline_color\", Color.BLACK)\n\t_list.add_theme_constant_override(\"outline_size\", 6)\n\tscroll.add_child(_list)\n\n\nfunc _engine() -> void:\n\tvar info := Engine.get_version_info()\n\t_add(\"Engine\", \"Godot\", \"works\", \"%s on %s\" % [info[\"string\"], OS.get_name()])\n\tvar method := RenderingServer.get_current_rendering_method()\n\tvar adapter := RenderingServer.get_video_adapter_name()\n\t_add(\"Drawing\", \"Renderer\", \"works\" if method != \"dummy\" else \"missing\", \"%s on %s\" % [method, adapter if adapter else \"no graphics card (headless)\"])\n\tif method == \"gl_compatibility\":\n\t\t_add(\"Drawing\", \"Forward+ effects\", \"missing\", \"The web player draws with the Compatibility renderer (WebGL 2), which leaves out %s. Glow, fog, shadows, shaders and particles still work.\" % FORWARD_ONLY)\n\tif RenderingServer.get_rendering_device() == null:\n\t\t_add(\"Drawing\", \"Compute shaders\", \"missing\", \"No RenderingDevice here, so no compute shaders; do the work in GDScript or fragment shaders.\")\n\tvar compression: Array[String] = []\n\tfor format: String in [\"etc2\", \"astc\", \"s3tc\", \"bptc\"]:\n\t\tif OS.has_feature(format):\n\t\t\tcompression.append(format.to_upper())\n\t_add(\"Drawing\", \"Texture compression\", \"works\" if compression else \"limited\", \", \".join(compression) if compression else \"None reported; pictures stay uncompressed (more memory).\")\n\n\nfunc _classes() -> void:\n\tfor group: String in CLASSES:\n\t\tvar missing: Array[String] = []\n\t\tvar present: Array[String] = []\n\t\tfor kind: String in CLASSES[group]:\n\t\t\tif ClassDB.class_exists(kind):\n\t\t\t\tpresent.append(kind)\n\t\t\telse:\n\t\t\t\tmissing.append(kind)\n\t\tif present:\n\t\t\t_add(group, \"%s parts\" % group, \"works\", \", \".join(present))\n\t\tif missing:\n\t\t\t_add(group, \"%s parts left out\" % group, \"missing\", \"Not in this build: %s\" % \", \".join(missing))\n\n\nfunc _threads() -> void:\n\t_add(\"Code\", \"Thread support\", \"works\" if OS.has_feature(\"threads\") else \"missing\", \"This build runs on several threads.\" if OS.has_feature(\"threads\") else \"This build is single-threaded: Thread objects don't run on their own, so long work freezes the game. Spread it over frames (await get_tree().process_frame).\")\n\tvar counter := [0]\n\tvar task := WorkerThreadPool.add_task(func() -> void: counter[0] += 1)\n\tWorkerThreadPool.wait_for_task_completion(task)\n\t_add(\"Code\", \"WorkerThreadPool\", \"works\" if counter[0] == 1 else \"limited\", \"Tasks run%s.\" % (\"\" if OS.has_feature(\"threads\") else \", but on the one main thread\"))\n\n\nfunc _memory() -> void:\n\tvar before := OS.get_static_memory_usage()\n\tvar big := PackedByteArray()\n\tvar wanted := 128 * 1024 * 1024\n\tvar error := big.resize(wanted)\n\tvar ok := error == OK and big.size() == wanted\n\tbig = PackedByteArray()\n\t_add(\"Engine\", \"Big memory (128 MB at once)\", \"works\" if ok else \"limited\", \"Took and gave back 128 MB.\" if ok else \"Couldn't take 128 MB at once (error %d).\" % error)\n\t_add(\"Engine\", \"Memory in use\", \"works\", \"%d MB at the start\" % int(before / 1048576.0))\n\n\nfunc _files() -> void:\n\tvar path := \"user://fcc_probe.txt\"\n\tvar file := FileAccess.open(path, FileAccess.WRITE)\n\tif file == null:\n\t\t_add(\"Files\", \"Saving (user://)\", \"missing\", \"Couldn't write: error %d\" % FileAccess.get_open_error())\n\t\treturn\n\tfile.store_string(\"probe\")\n\tfile.close()\n\tvar back := FileAccess.get_file_as_string(path)\n\tDirAccess.remove_absolute(path)\n\tif back != \"probe\":\n\t\t_add(\"Files\", \"Saving (user://)\", \"limited\", \"Wrote but read back '%s'\" % back)\n\telif _web() and not OS.is_userfs_persistent():\n\t\t_add(\"Files\", \"Saving (user://)\", \"limited\", \"Works while the game is open; it starts fresh each time (FCC's box keeps no game files).\")\n\telse:\n\t\t_add(\"Files\", \"Saving (user://)\", \"works\", \"Saves stay between runs.\" if OS.is_userfs_persistent() else \"Works.\")\n\t_add(\"Files\", \"Game files (res://)\", \"works\" if FileAccess.file_exists(\"res://probe.gd\") else \"limited\", \"Scripts, scenes and data read from the game's pack.\")\n\n\nfunc _data() -> void:\n\tvar parsed: Variant = JSON.parse_string('{\"a\": [1, 2, 3]}')\n\t_add(\"Code\", \"JSON\", \"works\" if parsed is Dictionary and (parsed as Dictionary)[\"a\"].size() == 3 else \"limited\", \"Read and write JSON.\")\n\tvar regex := RegEx.new()\n\tvar regex_ok := regex.compile(\"(\\\\d+)-(\\\\d+)\") == OK and regex.search(\"x 12-34\").get_string(2) == \"34\"\n\t_add(\"Code\", \"RegEx\", \"works\" if regex_ok else \"missing\", \"Patterns in text.\")\n\tvar expression := Expression.new()\n\tvar sum: Variant = null\n\tif expression.parse(\"2 + 3 * 4\") == OK:\n\t\tsum = expression.execute()\n\t_add(\"Code\", \"Expression\", \"works\" if sum == 14 else \"limited\", \"Maths typed in at run time.\")\n\tvar hashing := HashingContext.new()\n\thashing.start(HashingContext.HASH_SHA256)\n\thashing.update(\"abc\".to_utf8_buffer())\n\tvar digest := hashing.finish().hex_encode()\n\t_add(\"Code\", \"Hashing (SHA-256)\", \"works\" if digest.begins_with(\"ba7816bf\") else \"limited\", \"Checksums for saves and data.\")\n\tvar bytes := Crypto.new().generate_random_bytes(16)\n\t_add(\"Code\", \"Random bytes (Crypto)\", \"works\" if bytes.size() == 16 else \"limited\", \"Secure random numbers.\")\n\n\nfunc _images() -> void:\n\tvar image := Image.create_empty(32, 32, false, Image.FORMAT_RGBA8)\n\timage.fill(Color(0.2, 0.6, 1.0))\n\tvar formats := {\"PNG\": image.save_png_to_buffer(), \"WebP\": image.save_webp_to_buffer(true), \"JPEG\": image.save_jpg_to_buffer()}\n\tfor kind: String in formats:\n\t\tvar data: PackedByteArray = formats[kind]\n\t\tvar back := Image.new()\n\t\tvar error := ERR_UNAVAILABLE\n\t\tmatch kind:\n\t\t\t\"PNG\":\n\t\t\t\terror = back.load_png_from_buffer(data)\n\t\t\t\"WebP\":\n\t\t\t\terror = back.load_webp_from_buffer(data)\n\t\t\t\"JPEG\":\n\t\t\t\terror = back.load_jpg_from_buffer(data)\n\t\tvar ok := data.size() > 0 and error == OK and back.get_width() == 32\n\t\t_add(\"Pictures\", \"%s pictures\" % kind, \"works\" if ok else \"missing\", \"Made and read back at run time.\" if ok else \"Couldn't make or read one here.\")\n\tvar texture := ImageTexture.create_from_image(image)\n\t_add(\"Pictures\", \"Textures from pictures\", \"works\" if texture.get_width() == 32 else \"limited\", \"Image -> ImageTexture, for pictures loaded at run time.\")\n\n\nfunc _text() -> void:\n\tvar font := ThemeDB.fallback_font\n\tvar symbols := font.has_char(0x2605) and font.has_char(0x2694)\n\t_add(\"Text\", \"Letters (Latin)\", \"works\" if font.has_char(0x41) else \"missing\", \"The built-in font.\")\n\t_add(\"Text\", \"Symbols and emoji\", \"works\" if symbols else \"missing\", \"The built-in font has them.\" if symbols else \"Symbols like stars and swords (and emoji) show as empty boxes in the built-in font%s. Use words, draw them, or bring a font file into the game.\" % (\", and the web player has no system fonts to fall back on\" if _web() else \"\"))\n\tvar system := OS.get_system_fonts()\n\t_add(\"Text\", \"System fonts\", \"works\" if system.size() > 0 else \"missing\", \"%d found\" % system.size() if system.size() > 0 else \"None reachable from here.\")\n\tvar server := TextServerManager.get_primary_interface()\n\t_add(\"Text\", \"Text shaping\", \"works\", server.get_name() if server else \"unknown\")\n\tvar speech := DisplayServer.has_feature(DisplayServer.FEATURE_TEXT_TO_SPEECH) and DisplayServer.tts_get_voices().size() > 0\n\t_add(\"Text\", \"Speech (text to speech)\", \"works\" if speech else \"missing\", \"%d voices\" % DisplayServer.tts_get_voices().size() if speech else \"No voices reachable.\")\n\n\nfunc _controls() -> void:\n\tvar touch := DisplayServer.is_touchscreen_available()\n\t_add(\"Input\", \"Touch screen\", \"works\" if touch else \"missing\", \"Touches arrive as InputEventScreenTouch and Drag.\" if touch else \"No touch screen here.\")\n\t_add(\"Input\", \"Game controllers\", \"works\", \"%d connected now (they appear when a button is pressed).\" % Input.get_connected_joypads().size())\n\tvar keyboard := DisplayServer.has_feature(DisplayServer.FEATURE_VIRTUAL_KEYBOARD)\n\t_add(\"Input\", \"On-screen keyboard\", \"works\" if keyboard else \"limited\", \"LineEdit opens the phone's keyboard.\" if keyboard else \"Not reported; typing in a game may need a keyboard.\")\n\tvar tilt := Input.get_accelerometer()\n\t_add(\"Input\", \"Tilt (accelerometer)\", \"works\" if tilt != Vector3.ZERO else \"missing\", \"Reading %s\" % tilt if tilt != Vector3.ZERO else \"Reads zero here; use touch controls.\")\n\n\nfunc _physics() -> void:\n\tvar engine_name := str(ProjectSettings.get_setting(\"physics/3d/physics_engine\", \"DEFAULT\"))\n\tvar start := _ball.position.y\n\tfor _tick in 90:\n\t\tawait get_tree().physics_frame\n\tvar fell := _ball.position.y < start - 1.0\n\tvar rests := _ball.position.y > -0.2\n\t_add(\"Physics\", \"3D physics\" if engine_name == \"DEFAULT\" else \"3D physics (%s)\" % engine_name, \"works\" if fell and rests else \"limited\", \"A ball fell and landed on the floor.\" if fell and rests else \"The ball went from %.2f to %.2f.\" % [start, _ball.position.y])\n\tvar space := get_world_3d().direct_space_state\n\tvar ray := PhysicsRayQueryParameters3D.create(Vector3(0, 10, 0), Vector3(0, -10, 0))\n\tvar hit := space.intersect_ray(ray)\n\t_add(\"Physics\", \"Ray casts\", \"works\" if not hit.is_empty() else \"limited\", \"Hit the %s.\" % (hit[\"collider\"] as Object).get_class() if not hit.is_empty() else \"Hit nothing.\")\n\n\nfunc _drawing() -> void:\n\tvar frames := 0\n\tvar clock := Time.get_ticks_msec()\n\twhile Time.get_ticks_msec() - clock < 2000:\n\t\tawait get_tree().process_frame\n\t\tframes += 1\n\tvar fps := frames * 1000.0 / maxf(1.0, Time.get_ticks_msec() - clock)\n\t_add(\"Drawing\", \"Frame rate (3D scene, shadows, particles, a shader)\", \"works\" if fps >= 30 else \"limited\", \"%d frames a second\" % roundi(fps))\n\tif DisplayServer.get_name() == \"headless\":\n\t\treturn\n\tvar picture := get_viewport().get_texture().get_image()\n\tif picture == null or picture.is_empty():\n\t\t_add(\"Drawing\", \"Reading the screen\", \"missing\", \"Couldn't read the drawn picture back.\")\n\t\treturn\n\tvar lit := 0\n\tvar samples := 0\n\tfor y in range(0, picture.get_height(), 24):\n\t\tfor x in range(0, picture.get_width(), 24):\n\t\t\tsamples += 1\n\t\t\tif picture.get_pixel(x, y).get_luminance() > 0.12:\n\t\t\t\tlit += 1\n\t_add(\"Drawing\", \"3D picture\", \"works\" if lit > 0 else \"limited\", \"Drew %dx%d; %d%% of it lit.\" % [picture.get_width(), picture.get_height(), roundi(100.0 * lit / maxf(1, samples))])\n\n\nfunc _sound() -> void:\n\t_add(\"Sound\", \"Sound output\", \"works\" if AudioServer.get_mix_rate() > 0 else \"missing\", \"%d Hz, %s\" % [AudioServer.get_mix_rate(), AudioServer.get_output_device()])\n\tvar player := AudioStreamPlayer.new()\n\tvar generator := AudioStreamGenerator.new()\n\tgenerator.buffer_length = 0.1\n\tplayer.stream = generator\n\t# Made-up sound needs stream playback (the web plays samples by default).\n\tplayer.playback_type = AudioServer.PLAYBACK_TYPE_STREAM\n\tplayer.volume_db = -80.0\n\tadd_child(player)\n\tplayer.play()\n\tvar playback := player.get_stream_playback() as AudioStreamGeneratorPlayback\n\tvar room := playback.get_frames_available() if playback else 0\n\t_add(\"Sound\", \"Made-up sound (AudioStreamGenerator)\", \"works\" if room > 0 else \"limited\", \"Room for %d frames.\" % room if room > 0 else \"No playback room here.\")\n\tplayer.queue_free()\n\n\nfunc _network() -> void:\n\tvar request := HTTPRequest.new()\n\trequest.timeout = 3.0\n\tadd_child(request)\n\tvar error := request.request(\"https://example.com/\")\n\tvar status := \"blocked\"\n\tvar detail := \"The game can't reach the internet (FCC's box has none, on purpose).\"\n\tif error == OK:\n\t\tvar answer: Array = await request.request_completed\n\t\tif int(answer[0]) == HTTPRequest.RESULT_SUCCESS:\n\t\t\tstatus = \"works\"\n\t\t\tdetail = \"Reached example.com.\"\n\tif not _web() and status == \"blocked\":\n\t\tstatus = \"limited\"\n\t\tdetail = \"No answer from example.com within 3 s.\"\n\t_add(\"Network\", \"Internet from the game\", status, detail)\n\trequest.queue_free()\n\n\nfunc _bridge() -> void:\n\tif not _web() or not Engine.has_singleton(\"JavaScriptBridge\"):\n\t\treturn\n\tvar value: Variant = JavaScriptBridge.eval(\"1 + 1\", true)\n\tif value == null:\n\t\t_add(\"Code\", \"JavaScriptBridge\", \"blocked\", \"Running the browser's JavaScript from the game is off in FCC's box (on purpose).\")\n\telse:\n\t\t_add(\"Code\", \"JavaScriptBridge\", \"works\", \"eval gave %s\" % value)\n\n\nfunc _report() -> void:\n\tvar lines: Array[String] = [\"What Godot can do here\", \"\"]\n\tfor status: String in [\"works\", \"limited\", \"missing\", \"blocked\"]:\n\t\tvar shown: Array[String] = []\n\t\tfor item in items:\n\t\t\tif item[\"status\"] == status:\n\t\t\t\tshown.append(\"- %s: %s\" % [item[\"name\"], item[\"detail\"]])\n\t\tif shown:\n\t\t\tlines.append({\"works\": \"WORKS\", \"limited\": \"LIMITED\", \"missing\": \"MISSING\", \"blocked\": \"BLOCKED ON PURPOSE\"}[status])\n\t\t\tlines.append_array(shown)\n\t\t\tlines.append(\"\")\n\t_say(\"\\n\".join(lines))\n\tprint(\"FCC_PROBE \" + JSON.stringify({\"version\": Engine.get_version_info()[\"string\"], \"items\": items}))\n","probe.tscn":"[gd_scene load_steps=2 format=3]\n\n[ext_resource type=\"Script\" path=\"res://probe.gd\" id=\"1\"]\n\n[node name=\"Probe\" type=\"Node3D\"]\nscript = ExtResource(\"1\")\n","project.godot":"; FCC's Godot probe: tries the engine's parts on the device it runs on and\n; reports what works, what is limited and what is missing. FCC Phone runs it\n; in its Godot box (What can Godot do on this phone?).\n\nconfig_version=5\n\n[application]\n\nconfig/name=\"FCC Godot probe\"\nrun/main_scene=\"res://probe.tscn\"\nconfig/features=PackedStringArray(\"4.7\")\n\n[display]\n\nwindow/size/viewport_width=720\nwindow/size/viewport_height=1280\nwindow/stretch/mode=\"canvas_items\"\nwindow/stretch/aspect=\"expand\"\n\n[physics]\n\ncommon/physics_ticks_per_second=60\n\n[audio]\n\ngeneral/text_to_speech=true\n"};
